INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1029984, 123489, 27293, '<td valign="top">=) Nice find. =)</td>', '=) Nice find. =)', '2004-11-24 00:03:19.000000', NULL, 1),
(1029996, 123510, 27293, '<td valign="top">Oh, could be such a nice photo, but the quality is just nonexistent...</td>', 'Oh, could be such a nice photo, but the quality is just nonexistent...', '2004-11-24 00:06:34.000000', NULL, 1),
(1030007, 123237, 18257, '<td valign="top">coool</td>', 'coool', '2004-11-24 00:08:36.000000', NULL, 1),
(1030008, 122543, 28141, '<td valign="top">Good concept, but the words seem to be the subject, so more of them should be in focus.</td>', 'Good concept, but the words seem to be the subject, so more of them should be in focus.', '2004-11-24 00:08:49.000000', NULL, 1),
(1030027, 123443, 26827, '<td valign="top">The bars being entirely silhoueted make them seem added in post.  If they had some toning, and were in sharper detail, they would give me a better sense of location.  An interesting photo, but a bit too isolated for me.</td>', 'The bars being entirely silhoueted make them seem added in post.  If they had some toning, and were in sharper detail, they would give me a better sense of location.  An interesting photo, but a bit too isolated for me.', '2004-11-24 00:12:26.000000', NULL, 1),
(1030031, 123295, 3102, '<td valign="top">If there had been a home Steelers game this week, I would have submitted a very similar shot!  :)  I think this represents the challenge well.</td>', 'If there had been a home Steelers game this week, I would have submitted a very similar shot!  :)  I think this represents the challenge well.', '2004-11-24 00:13:13.000000', NULL, 1),
(1030035, 123384, 26827, '<td valign="top">The players seem just a bit out of focus, might be a little over-exposed on the jerseys, and the angle is distracting.</td>', 'The players seem just a bit out of focus, might be a little over-exposed on the jerseys, and the angle is distracting.', '2004-11-24 00:13:59.000000', NULL, 1),
(1030036, 123028, 27293, '<td valign="top">The focus is way off... not even one of the toys is crisp...</td>', 'The focus is way off... not even one of the toys is crisp...', '2004-11-24 00:14:19.000000', NULL, 1),
(1030040, 123517, 22384, '<td valign="top">Great idea. The signs and stop lights really add to the message of the photo. The headlights running across the image are too much, maybe fewer streaks would keep the image to a more managable message for my eye. Brilliant colors.</td>', 'Great idea. The signs and stop lights really add to the message of the photo. The headlights running across the image are too much, maybe fewer streaks would keep the image to a more managable message for my eye. Brilliant colors.', '2004-11-24 00:15:20.000000', NULL, 1),
(1030042, 122902, 26827, '<td valign="top">To begin, I don''t understand the relation to the topic.  Otherwise, the image seems very flat in tonality, but nicely crisp.</td>', 'To begin, I don''t understand the relation to the topic.  Otherwise, the image seems very flat in tonality, but nicely crisp.', '2004-11-24 00:15:26.000000', NULL, 1),
(1030045, 122976, 22384, '<td valign="top">This image is too washed out for me. I don''t see anything to captivate me. Nice line in your subject, but the shadows distract for those elegant lines.</td>', 'This image is too washed out for me. I don''t see anything to captivate me. Nice line in your subject, but the shadows distract for those elegant lines.', '2004-11-24 00:16:30.000000', NULL, 1),
(1030046, 123028, 28141, '<td valign="top">Focus should be on your subjects, not the cloth below them.  Cute idea though.</td>', 'Focus should be on your subjects, not the cloth below them.  Cute idea though.', '2004-11-24 00:16:41.000000', NULL, 1),
(1030048, 123318, 26827, '<td valign="top">The angel of presentation makes this difficult to read.  I like the tone, but the incomplete isolation is distracting.  There are a few spots where the reflection from the light may be a bit too harsh, perhaps a more diffuse source.</td>', 'The angel of presentation makes this difficult to read.  I like the tone, but the incomplete isolation is distracting.  There are a few spots where the reflection from the light may be a bit too harsh, perhaps a more diffuse source.', '2004-11-24 00:17:14.000000', NULL, 1),
(1030051, 123217, 22384, '<td valign="top">This gives me the feeling of horror rather than authority; however, sometimes they are the same thing, aren''t they? I would have cropped the light on the brick wall out of the image, it distracts from your focal point, which is imposing.</td>', 'This gives me the feeling of horror rather than authority; however, sometimes they are the same thing, aren''t they? I would have cropped the light on the brick wall out of the image, it distracts from your focal point, which is imposing.', '2004-11-24 00:17:53.000000', NULL, 1),
(1030055, 122782, 26827, '<td valign="top">Cropping the top of this image so close to the dog''s head, gives me a really claustrophobic feel.  Maybe a little out of focus.</td>', 'Cropping the top of this image so close to the dog''s head, gives me a really claustrophobic feel.  Maybe a little out of focus.', '2004-11-24 00:18:29.000000', NULL, 1),
(1030058, 122843, 22384, '<td valign="top">Your focal point would have more impact if it were lit better and framed diferently. Interesting idea. I like the irony of your title. Very creative.</td>', 'Your focal point would have more impact if it were lit better and framed diferently. Interesting idea. I like the irony of your title. Very creative.', '2004-11-24 00:19:06.000000', NULL, 1),
(1030059, 122538, 8437, '<td valign="top">I love the composition in this picture. Very well done!</td>', 'I love the composition in this picture. Very well done!', '2004-11-24 00:19:34.000000', NULL, 1),
(1030064, 123528, 26827, '<td valign="top">The crop is either too tight on the figurine, or it should not be in the picture.  With the background shadow so hazy, the in-focus toy has almost all of my attention.  Perhaps the toy is a bit over-exposed, and the shadow too fuzzy.</td>', 'The crop is either too tight on the figurine, or it should not be in the picture.  With the background shadow so hazy, the in-focus toy has almost all of my attention.  Perhaps the toy is a bit over-exposed, and the shadow too fuzzy.', '2004-11-24 00:20:27.000000', NULL, 1),
(1030066, 122543, 22384, '<td valign="top">Interesting point of view. I like the gritty realism of the photo. I would like a more determined focal point so that the  message would come across more powerfully (get it- sorry, couldn''t help myself.) Very interesting contrast of line and curve.</td>', 'Interesting point of view. I like the gritty realism of the photo. I would like a more determined focal point so that the  message would come across more powerfully (get it- sorry, couldn''t help myself.) Very interesting contrast of line and curve.', '2004-11-24 00:21:23.000000', NULL, 1),
(1030067, 122491, 26827, '<td valign="top">An interesting shot, but I''m not sure exactly what it is, or how it relates to the challenge.  As it stands, I don''t care for the crop''s inclusion of part of the arch.</td>', 'An interesting shot, but I''m not sure exactly what it is, or how it relates to the challenge.  As it stands, I don''t care for the crop''s inclusion of part of the arch.', '2004-11-24 00:21:39.000000', NULL, 1),
(1030069, 123523, 22384, '<td valign="top">Interesting lighting and shadow. I am not sure what I think of the use of this as a symbol of authority. Perhaps an even more extreme angle, shot from below would convey the message better.</td>', 'Interesting lighting and shadow. I am not sure what I think of the use of this as a symbol of authority. Perhaps an even more extreme angle, shot from below would convey the message better.', '2004-11-24 00:22:44.000000', NULL, 1),
(1030070, 123237, 26827, '<td valign="top">Interesting and clever.  If the hands had just a bit more motion blur, or just a bit less, It would seem more complete.</td>', 'Interesting and clever.  If the hands had just a bit more motion blur, or just a bit less, It would seem more complete.', '2004-11-24 00:22:44.000000', NULL, 1),
(1030075, 123289, 8437, '<td valign="top">Great idea and I love the composition. However, I don''t think the colors work very well. Also, the background (the floor), is very distracting, like some parts were wet, or something. Maybe if you adjusted some settings in Photoshop (levels or curves), you could solve that problem.</td>', 'Great idea and I love the composition. However, I don''t think the colors work very well. Also, the background (the floor), is very distracting, like some parts were wet, or something. Maybe if you adjusted some settings in Photoshop (levels or curves), you could solve that problem.', '2004-11-24 00:23:26.000000', NULL, 1),
(1030076, 123432, 26827, '<td valign="top">Crisp, and good conversion to b/w.  The crispness is spoiled just the tiniest, by the motionblur of the writing hand.</td>', 'Crisp, and good conversion to b/w.  The crispness is spoiled just the tiniest, by the motionblur of the writing hand.', '2004-11-24 00:23:27.000000', NULL, 1),
(1030077, 123500, 27293, '<td valign="top">Uhm, unless this was shot in a country with left side driving, that was just a right turn on green, wasn''t it?</td>', 'Uhm, unless this was shot in a country with left side driving, that was just a right turn on green, wasn''t it?', '2004-11-24 00:23:38.000000', NULL, 1),
(1030079, 123531, 27293, '<td valign="top">=)</td>', '=)', '2004-11-24 00:24:16.000000', NULL, 1),
(1030081, 123460, 26827, '<td valign="top">Good capture.  I guess, because of the shooting situation, the crowd seems a bit over-exposed and grainy.  Comes across like a pic in the sports page.  Nice.</td>', 'Good capture.  I guess, because of the shooting situation, the crowd seems a bit over-exposed and grainy.  Comes across like a pic in the sports page.  Nice.', '2004-11-24 00:25:04.000000', NULL, 1),
(1030087, 122830, 8437, '<td valign="top">By the position of the talent, this photo begs to be centered, which is not. Also, a tiny more contrast would make it better, in my opinion. Overall, it''s a good concept.</td>', 'By the position of the talent, this photo begs to be centered, which is not. Also, a tiny more contrast would make it better, in my opinion. Overall, it''s a good concept.', '2004-11-24 00:26:16.000000', NULL, 1),
(1030088, 123495, 28141, '<td valign="top">Would be more interesting if not centered.</td>', 'Would be more interesting if not centered.', '2004-11-24 00:26:24.000000', NULL, 1),
(1030089, 123298, 26827, '<td valign="top">I''m not sure, but the text, and top of the gate, seems just the tiniest out of focus, or at least my eyes think they are.  I think the sign, certainly important, may be too important, not revealing enough of the scene.</td>', 'I''m not sure, but the text, and top of the gate, seems just the tiniest out of focus, or at least my eyes think they are.  I think the sign, certainly important, may be too important, not revealing enough of the scene.', '2004-11-24 00:26:43.000000', NULL, 1),
(1030090, 123251, 28771, '<td valign="top">Indeed it is. Reminds me of the things my old nana used to chase me with as a young lad. (5)</td>', 'Indeed it is. Reminds me of the things my old nana used to chase me with as a young lad. (5)', '2004-11-24 00:26:59.000000', NULL, 1),
(1030091, 122555, 22384, '<td valign="top">Great angle, it gives a dizzying effect which works well with the concept, but I would crop this a little tighter. It seems to be fading off the frame due to the shadow. That takes away from the imposing image the artist was  trying to convey, especially since the title makes a dare. I would also shoot the shot from below even more. Let the sign tower over the viewer.</td>', 'Great angle, it gives a dizzying effect which works well with the concept, but I would crop this a little tighter. It seems to be fading off the frame due to the shadow. That takes away from the imposing image the artist was  trying to convey, especially since the title makes a dare. I would also shoot the shot from below even more. Let the sign tower over the viewer.', '2004-11-24 00:27:03.000000', NULL, 1),
(1030092, 123452, 7553, '<td valign="top">Very nice, I was looking for a really good spiritual reference on here.  Nice job with the lighting!</td>', 'Very nice, I was looking for a really good spiritual reference on here.  Nice job with the lighting!', '2004-11-24 00:27:07.000000', NULL, 1),
(1030093, 122905, 8437, '<td valign="top">Love it!! Humorous, well developed, well composed, well acted. My favorite so far.</td>', 'Love it!! Humorous, well developed, well composed, well acted. My favorite so far.', '2004-11-24 00:27:28.000000', NULL, 1),
(1030096, 123455, 7553, '<td valign="top">Nice idea, I like, and the lighting is very even over all.</td>', 'Nice idea, I like, and the lighting is very even over all.', '2004-11-24 00:27:49.000000', NULL, 1),
(1030097, 123469, 26827, '<td valign="top">I don''t understand how this stringed instrument relates to the challenge.  The tones seem somewhat flat, and the border is a bit too large for my taste.</td>', 'I don''t understand how this stringed instrument relates to the challenge.  The tones seem somewhat flat, and the border is a bit too large for my taste.', '2004-11-24 00:28:16.000000', NULL, 1),
(1030098, 123341, 8437, '<td valign="top">Good boy :)<br/> <br/>I would like to see this picture with the background out of focus...</td>', 'Good boy :) I would like to see this picture with the background out of focus...', '2004-11-24 00:28:43.000000', NULL, 1),
(1030099, 123512, 23913, '<td valign="top">wounderful shot.<br/> <br/>i lov the grayscale of the whole image everything fits well<br/>1 thing though i am bothared by the sarrifs on the x instead of it looking leagle it kinda seems home done.(should have changed the font for that)<br/>thats all GL,-BC</td>', 'wounderful shot. i lov the grayscale of the whole image everything fits well1 thing though i am bothared by the sarrifs on the x instead of it looking leagle it kinda seems home done.(should have changed the font for that)thats all GL,-BC', '2004-11-24 00:29:00.000000', NULL, 1),
(1030101, 122285, 26827, '<td valign="top">There seems to be a lack of focal point in the image.  Nothing really holds my interest.  I also don''t see how this fits the challenge.</td>', 'There seems to be a lack of focal point in the image.  Nothing really holds my interest.  I also don''t see how this fits the challenge.', '2004-11-24 00:29:18.000000', NULL, 1),
(1030103, 123510, 10432, '<td valign="top">Good concept.  However, the photo is very dark &amp; flat - could use more contrast and light.<br/>Also, the radiator (?) and red eye could use some editing.</td>', 'Good concept.  However, the photo is very dark & flat - could use more contrast and light.Also, the radiator (?) and red eye could use some editing.', '2004-11-24 00:29:41.000000', NULL, 1),
(1030106, 123253, 27293, '<td valign="top">Well, i like the lens effect, but two empty (?) police cars make up for a pretty poor subject. The title doesn''t save this, although it is clever. sorry.</td>', 'Well, i like the lens effect, but two empty (?) police cars make up for a pretty poor subject. The title doesn''t save this, although it is clever. sorry.', '2004-11-24 00:30:21.000000', NULL, 1),
(1030107, 123397, 28771, '<td valign="top">Very interesting looking currency there fellow. This is a good photo, but there are are a few problems I have. The candle holder is quite splotched and the wax itself has melted in a way that is not attractive to me. Now this could hve added to a rustic effect you were going for, but instead the background or the material upon which the objects are placed appears a tad too clean. A wooden table would have worked nicely, I think. Take care. (5)</td>', 'Very interesting looking currency there fellow. This is a good photo, but there are are a few problems I have. The candle holder is quite splotched and the wax itself has melted in a way that is not attractive to me. Now this could hve added to a rustic effect you were going for, but instead the background or the material upon which the objects are placed appears a tad too clean. A wooden table would have worked nicely, I think. Take care. (5)', '2004-11-24 00:30:47.000000', NULL, 1),
(1030108, 122797, 22384, '<td valign="top">Great color combination. There is certain focal point, so I am unsure what is the authority here. The car seems to take the focal point. The use of the bars could offer an interesting take on authority, maybe cropping tightly to the man in front of the stop sign. The artist would have to play with it a bit to see if it would work. Just a thought.</td>', 'Great color combination. There is certain focal point, so I am unsure what is the authority here. The car seems to take the focal point. The use of the bars could offer an interesting take on authority, maybe cropping tightly to the man in front of the stop sign. The artist would have to play with it a bit to see if it would work. Just a thought.', '2004-11-24 00:30:59.000000', NULL, 1),
(1030109, 123515, 7553, '<td valign="top">Nice lighting.  Good eye, the angle is great, lots of lines to draw the eye.  The idea of a courthouse (authority) is projected very well here.</td>', 'Nice lighting.  Good eye, the angle is great, lots of lines to draw the eye.  The idea of a courthouse (authority) is projected very well here.', '2004-11-24 00:30:59.000000', NULL, 1),
(1030111, 123223, 27293, '<td valign="top">=) Funny, but the quality of the shot leave a bit to be desired.</td>', '=) Funny, but the quality of the shot leave a bit to be desired.', '2004-11-24 00:31:17.000000', NULL, 1),
(1030112, 123539, 29219, '<td valign="top">It took me a second to get it.  I think the rock looks too much like a sponge so it takes a second to get it.</td>', 'It took me a second to get it.  I think the rock looks too much like a sponge so it takes a second to get it.', '2004-11-24 00:31:31.000000', NULL, 1),
(1030115, 123517, 26827, '<td valign="top">I like the vivid colors, but with so many of them, I can''t seem to find any one focal point.  It ends up being somewhat restless, without a strong point.</td>', 'I like the vivid colors, but with so many of them, I can''t seem to find any one focal point.  It ends up being somewhat restless, without a strong point.', '2004-11-24 00:32:21.000000', NULL, 1),
(1030116, 123507, 7553, '<td valign="top">Nice work, the effect is very strking and stands out from the other photos.  And nobody''s gonna argue with that "authority" ;)</td>', 'Nice work, the effect is very strking and stands out from the other photos.  And nobody''s gonna argue with that "authority" ;)', '2004-11-24 00:32:58.000000', NULL, 1),
(1030118, 123487, 28771, '<td valign="top">I must sya that is an usual looking hand there. When I cover up the fingers it resembles a pale liver. The ring is interestin, but I do not see what it adds. And when that is the case it is only detracting. I might say the same about your chosen frame. Be well and be sure to get nie and full at Thanksgiving. (5)</td>', 'I must sya that is an usual looking hand there. When I cover up the fingers it resembles a pale liver. The ring is interestin, but I do not see what it adds. And when that is the case it is only detracting. I might say the same about your chosen frame. Be well and be sure to get nie and full at Thanksgiving. (5)', '2004-11-24 00:33:28.000000', NULL, 1),
(1030119, 123346, 23913, '<td valign="top">the clothing of the man is very noise tec. wise that bothers me at the level that the noise is.<br/> <br/>also the clutter(behind the man''s left sholder) and the pruple ©Maglight take away from the shot</td>', 'the clothing of the man is very noise tec. wise that bothers me at the level that the noise is. also the clutter(behind the man''s left sholder) and the pruple ©Maglight take away from the shot', '2004-11-24 00:33:35.000000', NULL, 1),
(1030120, 123495, 26827, '<td valign="top">I don''t really care for this one.  Without an actual shot of the fedex truck, or blur entirely crossing the frame, it doesn''t mesh for me.</td>', 'I don''t really care for this one.  Without an actual shot of the fedex truck, or blur entirely crossing the frame, it doesn''t mesh for me.', '2004-11-24 00:33:57.000000', NULL, 1),
(1030121, 123234, 7553, '<td valign="top">Great lighting work.  Nice use of the beads and cross to dispay a sense of authority</td>', 'Great lighting work.  Nice use of the beads and cross to dispay a sense of authority', '2004-11-24 00:34:22.000000', NULL, 1),
(1030123, 122469, 22384, '<td valign="top">I like the idea, because gadgets can rule your life. The title and the airplane don''t work for me. I really think the artist was on to something with the gadget idea. There are some great shape motif possibilities in this image. Creative, but undefined and to frenetic for me to grasp a focal point.</td>', 'I like the idea, because gadgets can rule your life. The title and the airplane don''t work for me. I really think the artist was on to something with the gadget idea. There are some great shape motif possibilities in this image. Creative, but undefined and to frenetic for me to grasp a focal point.', '2004-11-24 00:34:26.000000', NULL, 1),
(1030125, 123442, 26827, '<td valign="top">It mey just be me nit-picking, but the blue flag against the blue sky leaves me focusing on the pole.  Nice capture of a blowing flag.</td>', 'It mey just be me nit-picking, but the blue flag against the blue sky leaves me focusing on the pole.  Nice capture of a blowing flag.', '2004-11-24 00:34:54.000000', NULL, 1),
(1030127, 123507, 28771, '<td valign="top">This is a nice imiage that I think would do better in contests other that DPC. The overexposure gives this a nice feeling, not sure what, but I like it.  The clothes, however, do not speak old west to me. Keep on rustlin''. (6)</td>', 'This is a nice imiage that I think would do better in contests other that DPC. The overexposure gives this a nice feeling, not sure what, but I like it.  The clothes, however, do not speak old west to me. Keep on rustlin''. (6)', '2004-11-24 00:35:22.000000', NULL, 1),
(1030128, 123530, 26827, '<td valign="top">The converging lines of the building probably would have been interesting enough without the angle of the frame.  It''s a bit of a shame in an otherwise good shot the reflection on the "M" is so bright an over-exposed.</td>', 'The converging lines of the building probably would have been interesting enough without the angle of the frame.  It''s a bit of a shame in an otherwise good shot the reflection on the "M" is so bright an over-exposed.', '2004-11-24 00:36:09.000000', NULL, 1),
(1030129, 122658, 7553, '<td valign="top">Very forceful image of authority.  Excellent lighting and contrast.</td>', 'Very forceful image of authority.  Excellent lighting and contrast.', '2004-11-24 00:36:17.000000', NULL, 1),
(1030133, 123299, 23913, '<td valign="top">thats disturbing</td>', 'thats disturbing', '2004-11-24 00:37:24.000000', NULL, 1),
(1030135, 123249, 22384, '<td valign="top">This is brilliant. Nice use of muted color and great focus on the words of the ticket. I would like to see a little tighter focus or a little softer focus on the keys. Take it one way or the other. Right now it just seems that they are a tad soft unintentionally. Very nice photo. Framing is the key to why this photograph works for me. The corner of the summons just barely skimming the right edge of the frame and the placement of the keys and their movement out of the frame adds just the right tension. Sweet.</td>', 'This is brilliant. Nice use of muted color and great focus on the words of the ticket. I would like to see a little tighter focus or a little softer focus on the keys. Take it one way or the other. Right now it just seems that they are a tad soft unintentionally. Very nice photo. Framing is the key to why this photograph works for me. The corner of the summons just barely skimming the right edge of the frame and the placement of the keys and their movement out of the frame adds just the right tension. Sweet.', '2004-11-24 00:37:52.000000', NULL, 1),
(1030136, 123446, 7553, '<td valign="top">Good use of lighting and shadows to portray the authority of a parent.  Very forceful.  Good job.</td>', 'Good use of lighting and shadows to portray the authority of a parent.  Very forceful.  Good job.', '2004-11-24 00:37:53.000000', NULL, 1),
(1030137, 123412, 26827, '<td valign="top">While I haven''t gotten through all of the entries, this may well be the best shot of pie tins in this challenge.  The light is a bit too bright on the front of the "ship", and too dark on marvin.  It''s a bit out of focus and the background would be better without the light spot.  Also, a loose connection to the challenge.</td>', 'While I haven''t gotten through all of the entries, this may well be the best shot of pie tins in this challenge.  The light is a bit too bright on the front of the "ship", and too dark on marvin.  It''s a bit out of focus and the background would be better without the light spot.  Also, a loose connection to the challenge.', '2004-11-24 00:37:57.000000', NULL, 1),
(1030139, 123028, 22479, '<td valign="top">I think you''ve done a clever job with the props. The problem that I see here which makes this photo unacceptible is the fact that everything you want to focus on, is out of focus. Cameras can be quirky when it comes to focus, however you can always quickly double check, recompose and shoot again if needed.</td>', 'I think you''ve done a clever job with the props. The problem that I see here which makes this photo unacceptible is the fact that everything you want to focus on, is out of focus. Cameras can be quirky when it comes to focus, however you can always quickly double check, recompose and shoot again if needed.', '2004-11-24 00:38:11.000000', NULL, 1),
(1030143, 123381, 28771, '<td valign="top">That is interesting. I like that you have a butter knife and that you have a newspaper as the background. I''m not sure I understand your point though. Is it that government control drains one of his substance or soul?  I will not downrate you for not understanding. I think it  is a clever setup. (6)</td>', 'That is interesting. I like that you have a butter knife and that you have a newspaper as the background. I''m not sure I understand your point though. Is it that government control drains one of his substance or soul?  I will not downrate you for not understanding. I think it  is a clever setup. (6)', '2004-11-24 00:38:52.000000', NULL, 1),
(1030147, 122826, 26827, '<td valign="top">Focus is a bit off.  For the effect, the background my be a bit too uneven.  Without any sense of location or situation, the image lacks punch.</td>', 'Focus is a bit off.  For the effect, the background my be a bit too uneven.  Without any sense of location or situation, the image lacks punch.', '2004-11-24 00:39:32.000000', NULL, 1),
(1030149, 123538, 22479, '<td valign="top">Humerous, nice DOF and sky.</td>', 'Humerous, nice DOF and sky.', '2004-11-24 00:39:35.000000', NULL, 1),
(1030150, 123454, 7553, '<td valign="top">Very nice job.  nice angle.  gives a feeling of being very small.</td>', 'Very nice job.  nice angle.  gives a feeling of being very small.', '2004-11-24 00:39:50.000000', NULL, 1),
(1030152, 123478, 22384, '<td valign="top">I see this as defying authority. I am trying to figure out why the artist chose the Kind of Clubs. I am sure there was a reason. I like the lighting and the shape contrast of the linear shape of the card and the curves and shadows ow the subjects hands and in the hint of his face. Captivating photo.</td>', 'I see this as defying authority. I am trying to figure out why the artist chose the Kind of Clubs. I am sure there was a reason. I like the lighting and the shape contrast of the linear shape of the card and the curves and shadows ow the subjects hands and in the hint of his face. Captivating photo.', '2004-11-24 00:40:12.000000', NULL, 1),
(1030153, 122681, 22479, '<td valign="top">Nice concept, image too small however. Otherwise the focus is good, and the shot is well exposed.</td>', 'Nice concept, image too small however. Otherwise the focus is good, and the shot is well exposed.', '2004-11-24 00:40:13.000000', NULL, 1),
(1030157, 123447, 26827, '<td valign="top">A couple of small things:  The crop is a little low on the helmet.  The depth-of-field would be better a bit more centeredon cobra commander.  It feels unbalanced with one arm clear and one really blurry.</td>', 'A couple of small things:  The crop is a little low on the helmet.  The depth-of-field would be better a bit more centeredon cobra commander.  It feels unbalanced with one arm clear and one really blurry.', '2004-11-24 00:41:06.000000', NULL, 1),
(1030159, 123055, 22384, '<td valign="top">Powerful image. Great angle and crisp image with a soft background, which works well. I would like to see a greater contrast, blacker blacks and pinker pinks.</td>', 'Powerful image. Great angle and crisp image with a soft background, which works well. I would like to see a greater contrast, blacker blacks and pinker pinks.', '2004-11-24 00:41:34.000000', NULL, 1),
(1030161, 123535, 26827, '<td valign="top">The paper, which seems to be the focal point, is a little blurry, and at such a straight angle to the camera, it is very difficult to read what it says.</td>', 'The paper, which seems to be the focal point, is a little blurry, and at such a straight angle to the camera, it is very difficult to read what it says.', '2004-11-24 00:42:17.000000', NULL, 1),
(1030162, 122419, 23913, '<td valign="top">intrusting angle.<br/>not often shot from especaly the way the feet/shoes apear to be on the camera its self.</td>', 'intrusting angle.not often shot from especaly the way the feet/shoes apear to be on the camera its self.', '2004-11-24 00:42:27.000000', NULL, 1),
(1030166, 123223, 22479, '<td valign="top">I think your border added a shadow effect which by basic rules may be subject to disqualification. Otherwise, the focus is good, but exposure seems slightly blown on the sign. I like the sheen on the dog.</td>', 'I think your border added a shadow effect which by basic rules may be subject to disqualification. Otherwise, the focus is good, but exposure seems slightly blown on the sign. I like the sheen on the dog.', '2004-11-24 00:42:56.000000', NULL, 1),
