(1030312, 122543, 26827, '<td valign="top">Very nice.  Good depth-of-field.  Nice and gritty.</td>', 'Very nice.  Good depth-of-field.  Nice and gritty.', '2004-11-24 01:16:01.000000', NULL, 1),
