(1030316, 123483, 26827, '<td valign="top">The title completely ruins this for me.  Probably a "5" on its own, a little soft, not a balance composition.</td>', 'The title completely ruins this for me.  Probably a "5" on its own, a little soft, not a balance composition.', '2004-11-24 01:16:50.000000', NULL, 1),
(1030318, 123395, 22479, '<td valign="top">Nice exposure and DOF.</td>', 'Nice exposure and DOF.', '2004-11-24 01:17:44.000000', NULL, 1),
(1030319, 123455, 26827, '<td valign="top">Had to add the car, just to it was 3-d, huh?  Cute, the border meshes well with the borders of the spaces.  You seem to have captured the texture on the board well, but the car is a little off.</td>', 'Had to add the car, just to it was 3-d, huh?  Cute, the border meshes well with the borders of the spaces.  You seem to have captured the texture on the board well, but the car is a little off.', '2004-11-24 01:17:48.000000', NULL, 1),
(1030321, 123046, 26827, '<td valign="top">Nice isolation via depth-of-field, but relatively uninspiring.</td>', 'Nice isolation via depth-of-field, but relatively uninspiring.', '2004-11-24 01:18:21.000000', NULL, 1),
(1030323, 123046, 22384, '<td valign="top">I love the colors. Nice brilliant red of the sign, then the muted burgandies of the branches and leaves with the backdrop of the snow and buildings. I like the intense focus on your subject with the softness of the background. I really want to straighten the sign, though. It should be ramrod straight to convey the immutable messge.</td>', 'I love the colors. Nice brilliant red of the sign, then the muted burgandies of the branches and leaves with the backdrop of the snow and buildings. I like the intense focus on your subject with the softness of the background. I really want to straighten the sign, though. It should be ramrod straight to convey the immutable messge.', '2004-11-24 01:18:29.000000', NULL, 1),
(1030324, 122538, 23394, '<td valign="top">sick, sick, sick.  i''m sure you had a lot of fun doing this.  next time, you might want to submit a slightly larger image (you can go up to 640 pixels on the longest side).</td>', 'sick, sick, sick.  i''m sure you had a lot of fun doing this.  next time, you might want to submit a slightly larger image (you can go up to 640 pixels on the longest side).', '2004-11-24 01:18:42.000000', NULL, 1),
(1030329, 122538, 26827, '<td valign="top">I don''t quite get this one.  It''s a bit outside the box.  Ideal for a "slasher pic" challenge, but a bit gory for this.</td>', 'I don''t quite get this one.  It''s a bit outside the box.  Ideal for a "slasher pic" challenge, but a bit gory for this.', '2004-11-24 01:19:45.000000', NULL, 1),
(1030330, 123507, 25952, '<td valign="top">this is good but so post processed, wish i could see the original. i dont really have anything against the post processing, but this doesnt look like a photograph really. other than that its one of the better ones ive seen so far.</td>', 'this is good but so post processed, wish i could see the original. i dont really have anything against the post processing, but this doesnt look like a photograph really. other than that its one of the better ones ive seen so far.', '2004-11-24 01:19:52.000000', NULL, 1),
(1030331, 123444, 23394, '<td valign="top">the lighting and general composition are ok, but the focus is too soft.</td>', 'the lighting and general composition are ok, but the focus is too soft.', '2004-11-24 01:20:15.000000', NULL, 1),
(1030332, 123508, 22479, '<td valign="top">The focus is soft on this shot, and there''s insufficient contrast. Teen''s eyeball is a funky looking. I think you had a nice concept but the execution suffered from technicalities.</td>', 'The focus is soft on this shot, and there''s insufficient contrast. Teen''s eyeball is a funky looking. I think you had a nice concept but the execution suffered from technicalities.', '2004-11-24 01:20:17.000000', NULL, 1),
(1030333, 123034, 26827, '<td valign="top">Very nic, except the foreground looks a little out of focus.</td>', 'Very nic, except the foreground looks a little out of focus.', '2004-11-24 01:20:29.000000', NULL, 1),
(1030335, 122353, 23913, '<td valign="top">the reflection is a bothersome element  also it looks as if the sign is just sprayemounted to a pice of cardboard.</td>', 'the reflection is a bothersome element  also it looks as if the sign is just sprayemounted to a pice of cardboard.', '2004-11-24 01:21:14.000000', NULL, 1),
(1030336, 123455, 22384, '<td valign="top">Funny. Beautiful crisp image. I would have cropped it differently, much tighter on the card. I would have the card on top of Luxury Tax and Park Place, with those sections partially visible beneath it. Or I would crop them out entirely, letting the question marks complement the card. Just a thought.</td>', 'Funny. Beautiful crisp image. I would have cropped it differently, much tighter on the card. I would have the card on top of Luxury Tax and Park Place, with those sections partially visible beneath it. Or I would crop them out entirely, letting the question marks complement the card. Just a thought.', '2004-11-24 01:21:17.000000', NULL, 1),
(1030337, 123480, 26827, '<td valign="top">Pretty good portrait.  I like the desaturated tone, but the crop on the top doesn''t seem to be quite in the right place.</td>', 'Pretty good portrait.  I like the desaturated tone, but the crop on the top doesn''t seem to be quite in the right place.', '2004-11-24 01:21:26.000000', NULL, 1),
(1030338, 123458, 23394, '<td valign="top">interesting perspective and lighting, but doubt if the image will be recognized as a capture of strong authority.</td>', 'interesting perspective and lighting, but doubt if the image will be recognized as a capture of strong authority.', '2004-11-24 01:21:55.000000', NULL, 1),
(1030339, 123395, 26827, '<td valign="top">The softness is ok, but witha  sepia, or aged toning, would be great, with the b/w, it doesn''t help.  Going sharper with grain, would be good for b/w.</td>', 'The softness is ok, but witha  sepia, or aged toning, would be great, with the b/w, it doesn''t help.  Going sharper with grain, would be good for b/w.', '2004-11-24 01:22:22.000000', NULL, 1),
(1030342, 122313, 26827, '<td valign="top">With the massive over-exposure of hte sky, and lens flare, I hardly see anything else inthis picture.  Not good.  Also, I don''t see it''s relation to the topic.</td>', 'With the massive over-exposure of hte sky, and lens flare, I hardly see anything else inthis picture.  Not good.  Also, I don''t see it''s relation to the topic.', '2004-11-24 01:23:01.000000', NULL, 1),
(1030343, 123507, 14012, '<td valign="top">don''t know how this will go over on DPC, but from what I''ve seen thus far, this is by far the best entry in the challenge. I really like the editing.</td>', 'don''t know how this will go over on DPC, but from what I''ve seen thus far, this is by far the best entry in the challenge. I really like the editing.', '2004-11-24 01:23:14.000000', NULL, 1),
(1030344, 122469, 23394, '<td valign="top">sorry, but this comes across as a snapshot of a bunch of stuff in the floor.  not quite sure how this relates to authority.</td>', 'sorry, but this comes across as a snapshot of a bunch of stuff in the floor.  not quite sure how this relates to authority.', '2004-11-24 01:23:18.000000', NULL, 1),
(1030346, 123450, 22384, '<td valign="top">Great angle. Great expression on your subject''s face. I like that she is looking to the future, almost seeing her future generations. I see pride and determination in this woman''s face. The only flaw I see is the glare on her glasses. I know that is so hard to get rid of, but it really does distract from her face. Nice thought out. Powerful image.</td>', 'Great angle. Great expression on your subject''s face. I like that she is looking to the future, almost seeing her future generations. I see pride and determination in this woman''s face. The only flaw I see is the glare on her glasses. I know that is so hard to get rid of, but it really does distract from her face. Nice thought out. Powerful image.', '2004-11-24 01:23:29.000000', NULL, 1),
(1030347, 123024, 26827, '<td valign="top">Interesting image.  The border is excessive for my taste, and the connection to the topic tenuous.</td>', 'Interesting image.  The border is excessive for my taste, and the connection to the topic tenuous.', '2004-11-24 01:23:39.000000', NULL, 1),
(1030348, 123517, 23394, '<td valign="top">wild lighting and colors here, but i''m not really getting a feel for authority</td>', 'wild lighting and colors here, but i''m not really getting a feel for authority', '2004-11-24 01:24:14.000000', NULL, 1),
(1030349, 123394, 26827, '<td valign="top">But, shouldn''t it be the cat talking? :)</td>', 'But, shouldn''t it be the cat talking? :)', '2004-11-24 01:24:15.000000', NULL, 1),
(1030350, 123394, 22384, '<td valign="top">Good thing someone is taking charge, or cats would rule the world. Cute image. Nice sense of fun and interaction between the cat and the woman.</td>', 'Good thing someone is taking charge, or cats would rule the world. Cute image. Nice sense of fun and interaction between the cat and the woman.', '2004-11-24 01:24:42.000000', NULL, 1),
(1030353, 122551, 26827, '<td valign="top">An interesting sibject, but without more contrast to the background, it feels a little indistince between the statue and the sky in some places.</td>', 'An interesting sibject, but without more contrast to the background, it feels a little indistince between the statue and the sky in some places.', '2004-11-24 01:25:41.000000', NULL, 1),
(1030354, 123500, 23913, '<td valign="top">well shot nice image<br/> <br/>it seems to be on an uncanny tilt though next time maybe try to keep the camera level.<br/>maybe it sliped since the green and red lights appear to have a trail.</td>', 'well shot nice image it seems to be on an uncanny tilt though next time maybe try to keep the camera level.maybe it sliped since the green and red lights appear to have a trail.', '2004-11-24 01:25:44.000000', NULL, 1),
(1030355, 123507, 28629, '<td valign="top">This is very nice</td>', 'This is very nice', '2004-11-24 01:26:25.000000', NULL, 1),
(1030357, 123336, 23394, '<td valign="top">just what is ''white man''s burden''?  as far as the image goes, i guess i''m seeing a gun barrel; beyond that, i really can''t tell.</td>', 'just what is ''white man''s burden''?  as far as the image goes, i guess i''m seeing a gun barrel; beyond that, i really can''t tell.', '2004-11-24 01:27:00.000000', NULL, 1),
(1030358, 123290, 22384, '<td valign="top">I don''t know how this convey''s authority, but I like the personality the photographer captured in the dog''s expression. He looks unhappy to me, eduring this bath. The lighting is a distraction on the dog, but it enhances the human arm.</td>', 'I don''t know how this convey''s authority, but I like the personality the photographer captured in the dog''s expression. He looks unhappy to me, eduring this bath. The lighting is a distraction on the dog, but it enhances the human arm.', '2004-11-24 01:27:14.000000', NULL, 1),
(1030359, 123510, 22479, '<td valign="top">Model is appropriate. There are several factors which make this photograph unacceptable. <br/> <br/>- Contrast. Lack thereof. This shot could have used a nice boost in contrast. <br/>- Framing. Could have cropped off the distracting white at the lower right corner and upper right corner, and the female could have been shot in front of a more interesting backdrop. A slight rotation clockwise could have improved this.<br/>- Red eye. Under the basic editing rules, this is problematic. I think instead of shooting her face on, a different angle would have been more compelling and eliminated the red eye, to boot.<br/>- Detail. Focus is soft and the resolving capability of the camera is rather dismal. Perhaps a tighter shot would have brough out more details which was lost with this particular composition.<br/> <br/>Given these considerations I can''t rate this very highly, sorry.<br/></td>', 'Model is appropriate. There are several factors which make this photograph unacceptable.  - Contrast. Lack thereof. This shot could have used a nice boost in contrast. - Framing. Could have cropped off the distracting white at the lower right corner and upper right corner, and the female could have been shot in front of a more interesting backdrop. A slight rotation clockwise could have improved this.- Red eye. Under the basic editing rules, this is problematic. I think instead of shooting her face on, a different angle would have been more compelling and eliminated the red eye, to boot.- Detail. Focus is soft and the resolving capability of the camera is rather dismal. Perhaps a tighter shot would have brough out more details which was lost with this particular composition. Given these considerations I can''t rate this very highly, sorry.', '2004-11-24 01:27:26.000000', NULL, 1),
(1030360, 123500, 23394, '<td valign="top">wish you''d corrected the tilt on the horizon first.</td>', 'wish you''d corrected the tilt on the horizon first.', '2004-11-24 01:28:09.000000', NULL, 1),
(1030361, 123452, 28629, '<td valign="top">This is very dramatic and powerful. Nice Picture</td>', 'This is very dramatic and powerful. Nice Picture', '2004-11-24 01:28:33.000000', NULL, 1),
(1030362, 123346, 22384, '<td valign="top">I thought this was basic editing so I am not sure if this qualifies. The image is fuzzy, but it certainly is a great idea. Very funny. Great expression on both faces.</td>', 'I thought this was basic editing so I am not sure if this qualifies. The image is fuzzy, but it certainly is a great idea. Very funny. Great expression on both faces.', '2004-11-24 01:28:43.000000', NULL, 1),
(1030365, 123226, 23913, '<td valign="top">nice angle but the screen appears to be blown out the window to be exact.</td>', 'nice angle but the screen appears to be blown out the window to be exact.', '2004-11-24 01:28:46.000000', NULL, 1),
(1030366, 123016, 28629, '<td valign="top">shouldve cropped the bottom more i think...</td>', 'shouldve cropped the bottom more i think...', '2004-11-24 01:29:33.000000', NULL, 1),
(1030367, 123441, 23394, '<td valign="top">a little on the dark side.  cropping is a little uneven, as well.  while i can recognize time as a form of authority, all i see here is a snapshot of a clock.</td>', 'a little on the dark side.  cropping is a little uneven, as well.  while i can recognize time as a form of authority, all i see here is a snapshot of a clock.', '2004-11-24 01:29:46.000000', NULL, 1),
(1030368, 122391, 19952, '<td valign="top">This is such a vibrant and colorful photo and you do a great job of focusing attention directly on your primary subject. Really nice shot.</td>', 'This is such a vibrant and colorful photo and you do a great job of focusing attention directly on your primary subject. Really nice shot.', '2004-11-24 01:29:47.000000', NULL, 1),
(1030369, 123412, 22384, '<td valign="top">Great idea and lighting. I think I would make the angle (point of view) even more intense and shoot up ar Marvin. I don''t know how this really meets the challenge, but it sure is fun!</td>', 'Great idea and lighting. I think I would make the angle (point of view) even more intense and shoot up ar Marvin. I don''t know how this really meets the challenge, but it sure is fun!', '2004-11-24 01:29:52.000000', NULL, 1),
(1030370, 123384, 22479, '<td valign="top">Nice focus, contrast, and saturation. Composition suffers however from your particular crop. I would have cropped the coach and player closer to the inner 1/3 of the photograph and perhaps changed the aspect ratio.</td>', 'Nice focus, contrast, and saturation. Composition suffers however from your particular crop. I would have cropped the coach and player closer to the inner 1/3 of the photograph and perhaps changed the aspect ratio.', '2004-11-24 01:30:04.000000', NULL, 1),
(1030373, 123345, 23913, '<td valign="top">nice angle, well shot<br/>the fact that it is in B&amp;W adds to the image IMO</td>', 'nice angle, well shotthe fact that it is in B&W adds to the image IMO', '2004-11-24 01:30:39.000000', NULL, 1),
(1030375, 123363, 22384, '<td valign="top">Funny picture, great job capturing the humor and ability to laugh at one''s self in this woman. I like the green shir and the bround eyes. Nice job with no reflection on the glasses. Did you remove the frames? If not, how did you do that? Great framing. Great picture.</td>', 'Funny picture, great job capturing the humor and ability to laugh at one''s self in this woman. I like the green shir and the bround eyes. Nice job with no reflection on the glasses. Did you remove the frames? If not, how did you do that? Great framing. Great picture.', '2004-11-24 01:31:22.000000', NULL, 1),
(1030376, 122285, 23913, '<td valign="top">i don''t see where authority has a place in this shot at all.</td>', 'i don''t see where authority has a place in this shot at all.', '2004-11-24 01:31:36.000000', NULL, 1),
(1030377, 123509, 29486, '<td valign="top">Good concept but for some reason the photo looks like it was printed in the 60''s. It''s got a yellowish(?) tint that I don''t care for. Don''t know if thats the white balance being out of sync or by design.</td>', 'Good concept but for some reason the photo looks like it was printed in the 60''s. It''s got a yellowish(?) tint that I don''t care for. Don''t know if thats the white balance being out of sync or by design.', '2004-11-24 01:32:00.000000', NULL, 1),
(1030380, 123507, 19952, '<td valign="top">Very cool high key / high contrast photo that works perfectly for this challenge. Nice job!</td>', 'Very cool high key / high contrast photo that works perfectly for this challenge. Nice job!', '2004-11-24 01:32:37.000000', NULL, 1),
(1030381, 122826, 23394, '<td valign="top">nice idea.  lighting is a little strong, and cropping a little tight.  the imperfections in your backdrop are a little distracting as well. focus seems a little soft.  don''t know what type of camera you are using, or lens for that matter, but in this controlled environment, you should be able to get the focus absolutely razor sharp.   this looks like it would be a fun shot to revisit.</td>', 'nice idea.  lighting is a little strong, and cropping a little tight.  the imperfections in your backdrop are a little distracting as well. focus seems a little soft.  don''t know what type of camera you are using, or lens for that matter, but in this controlled environment, you should be able to get the focus absolutely razor sharp.   this looks like it would be a fun shot to revisit.', '2004-11-24 01:33:02.000000', NULL, 1),
(1030382, 122538, 22479, '<td valign="top">Gruesome. I think I have that same exact cleaver. :) <br/> <br/>Subject matter: inappropriate. Nurses don''t usually get away with slaughter and thus they have no authority in this sense. Hmm...she looks pretty crazy though and thus defies authority. Bottom line is though that she''s small framed and I think I could take her out.<br/> <br/>Photographic merits: very high potential. The expression on her face is perfect. The lighting is hard and appropriate for the subject matter. You could have made this larger and thus had greater visual impact.<br/> <br/>Overall this has a lot of potential. One of the more interesting entries for sure. Had this photograph utilized the full potential of 640 pixel dimensions, I would easily give this one the highest rating.</td>', 'Gruesome. I think I have that same exact cleaver. :)  Subject matter: inappropriate. Nurses don''t usually get away with slaughter and thus they have no authority in this sense. Hmm...she looks pretty crazy though and thus defies authority. Bottom line is though that she''s small framed and I think I could take her out. Photographic merits: very high potential. The expression on her face is perfect. The lighting is hard and appropriate for the subject matter. You could have made this larger and thus had greater visual impact. Overall this has a lot of potential. One of the more interesting entries for sure. Had this photograph utilized the full potential of 640 pixel dimensions, I would easily give this one the highest rating.', '2004-11-24 01:33:13.000000', NULL, 1),
(1030385, 122555, 22479, '<td valign="top">Interesting angle. I like the saturation, focus, and clarity.</td>', 'Interesting angle. I like the saturation, focus, and clarity.', '2004-11-24 01:33:54.000000', NULL, 1),
(1030387, 123528, 22479, '<td valign="top">Awesome lighting! I think this is a rather small sized entry and would be more visually impacting if you made full use of 640 pixels. Still, a strong entry.</td>', 'Awesome lighting! I think this is a rather small sized entry and would be more visually impacting if you made full use of 640 pixels. Still, a strong entry.', '2004-11-24 01:34:10.000000', NULL, 1),
(1030388, 123016, 26827, '<td valign="top">It seems the focus is on the branches, not the sign.  Other than that, very nice.</td>', 'It seems the focus is on the branches, not the sign.  Other than that, very nice.', '2004-11-24 01:34:21.000000', NULL, 1),
(1030390, 123478, 28629, '<td valign="top">Very good!</td>', 'Very good!', '2004-11-24 01:34:37.000000', NULL, 1),
(1030391, 123288, 23394, '<td valign="top">while i truly believe in the power of prayer, this image, to me, is more of a snapshot than an image that evokes the authority of a higher being.  maybe if shot without the flash, or from a different angle, it might be more powerful.</td>', 'while i truly believe in the power of prayer, this image, to me, is more of a snapshot than an image that evokes the authority of a higher being.  maybe if shot without the flash, or from a different angle, it might be more powerful.', '2004-11-24 01:34:59.000000', NULL, 1),
(1030392, 123455, 22479, '<td valign="top">Clever, however image is somewhat flat.</td>', 'Clever, however image is somewhat flat.', '2004-11-24 01:35:13.000000', NULL, 1),
(1030393, 123338, 22479, '<td valign="top">Nice angle. I wish you had increased the DOF a hair. Overall a strong entry.</td>', 'Nice angle. I wish you had increased the DOF a hair. Overall a strong entry.', '2004-11-24 01:35:46.000000', NULL, 1),
(1030394, 123391, 26827, '<td valign="top">The flag is competeing with the lighthouse for being a focal point.  they are too close in height, and they are both sharp...  If one or the other were less important, I''d like the shot more.</td>', 'The flag is competeing with the lighthouse for being a focal point.  they are too close in height, and they are both sharp...  If one or the other were less important, I''d like the shot more.', '2004-11-24 01:35:47.000000', NULL, 1),
(1030395, 122830, 23394, '<td valign="top">nice bw.  lighting leaves the detail on the back a little soft.  while this image evokes a sense of power, it does not speak to me of authority.</td>', 'nice bw.  lighting leaves the detail on the back a little soft.  while this image evokes a sense of power, it does not speak to me of authority.', '2004-11-24 01:36:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1030396, 123469, 23913, '<td valign="top">this shot appears very low res. and has (IMHO) nothing to do with (and fails to be a "great example of) authority"<br/>sorry it is just to unclear.</td>', 'this shot appears very low res. and has (IMHO) nothing to do with (and fails to be a "great example of) authority"sorry it is just to unclear.', '2004-11-24 01:36:06.000000', NULL, 1),
(1030399, 122379, 22479, '<td valign="top">Nice night shot. I like the angle. Exposure is excellent.</td>', 'Nice night shot. I like the angle. Exposure is excellent.', '2004-11-24 01:36:41.000000', NULL, 1),
(1030400, 123024, 23913, '<td valign="top">like the grayscale</td>', 'like the grayscale', '2004-11-24 01:36:53.000000', NULL, 1),
(1030401, 122953, 22479, '<td valign="top">Nice sky except for the blemish. Sharp, detailed, nice contrast and tone.</td>', 'Nice sky except for the blemish. Sharp, detailed, nice contrast and tone.', '2004-11-24 01:37:24.000000', NULL, 1),
(1030402, 122681, 26827, '<td valign="top">Seems out of focus.  It is very hard to make out any detail at my viewing esolution.  Composition/action is no that interesting to me.  Well exposed.</td>', 'Seems out of focus.  It is very hard to make out any detail at my viewing esolution.  Composition/action is no that interesting to me.  Well exposed.', '2004-11-24 01:37:25.000000', NULL, 1),
