(1030405, 123028, 26827, '<td valign="top">Interesting set-up.  The focal plane is way off.  Too bad, it''s a cute idea.</td>', 'Interesting set-up.  The focal plane is way off.  Too bad, it''s a cute idea.', '2004-11-24 01:37:57.000000', NULL, 1),
(1030407, 123432, 22479, '<td valign="top">Strong entry. I like the motion blur. Everything is in focus. Framed well.</td>', 'Strong entry. I like the motion blur. Everything is in focus. Framed well.', '2004-11-24 01:38:27.000000', NULL, 1),
(1030408, 123217, 23394, '<td valign="top">when i lived in an apartment, i was more concerned about the man in the basement, who had control over the heating, cooling, and plumbing for the entire building...that was authority.  this image does not really evoke an impression of authority for me.  what rules is he going to enforce?  or is he just a scary dude?</td>', 'when i lived in an apartment, i was more concerned about the man in the basement, who had control over the heating, cooling, and plumbing for the entire building...that was authority.  this image does not really evoke an impression of authority for me.  what rules is he going to enforce?  or is he just a scary dude?', '2004-11-24 01:38:30.000000', NULL, 1),
(1030410, 123538, 26827, '<td valign="top">Nice.  Colors on the signs are a little dark.</td>', 'Nice.  Colors on the signs are a little dark.', '2004-11-24 01:38:36.000000', NULL, 1),
