(1031224, 123449, 9939, '<td valign="top">hmmm, too bad about that tree. Hard to tell what he''s doing/who he is- so authority here isn''t defined.</td>', 'hmmm, too bad about that tree. Hard to tell what he''s doing/who he is- so authority here isn''t defined.', '2004-11-24 11:40:47.000000', NULL, 1),
(1031225, 123317, 27158, '<td valign="top">beautiful shot...this bird''s ready to tell it like it is! Nice color and composition!</td>', 'beautiful shot...this bird''s ready to tell it like it is! Nice color and composition!', '2004-11-24 11:40:55.000000', NULL, 1),
(1031229, 123033, 9939, '<td valign="top">funny! Nice setup.</td>', 'funny! Nice setup.', '2004-11-24 11:41:58.000000', NULL, 1),
(1031230, 122790, 27158, '<td valign="top">NIce sky and composition<br/></td>', 'NIce sky and composition', '2004-11-24 11:42:07.000000', NULL, 1),
(1031231, 122953, 26827, '<td valign="top">The image itself could use a more contrasting color somewhere in it.  The brown and green  don''t "pop" anywhere.  I don''t see any major technical flaws.  Interesting that you caught the moon in the sky.  The picture fits the challenge, but the title throws me.  In the US it''s a phrase used by the military to denote their policy on gay servicemembers.  THe government won''t ask, and they shouldn''t tell, or they will be kicked out.  How hat relates is a little, no completely, obscure to me.</td>', 'The image itself could use a more contrasting color somewhere in it.  The brown and green  don''t "pop" anywhere.  I don''t see any major technical flaws.  Interesting that you caught the moon in the sky.  The picture fits the challenge, but the title throws me.  In the US it''s a phrase used by the military to denote their policy on gay servicemembers.  THe government won''t ask, and they shouldn''t tell, or they will be kicked out.  How hat relates is a little, no completely, obscure to me.', '2004-11-24 11:42:09.000000', NULL, 1),
(1031232, 123495, 20056, '<td valign="top">Nice! maybe STOP signal is a little centric</td>', 'Nice! maybe STOP signal is a little centric', '2004-11-24 11:42:16.000000', NULL, 1),
(1031234, 122830, 26827, '<td valign="top">Nice authoritative pose, but the one highlight on his head is a bit much when the rest are perfect.</td>', 'Nice authoritative pose, but the one highlight on his head is a bit much when the rest are perfect.', '2004-11-24 11:42:49.000000', NULL, 1),
(1031235, 122905, 9939, '<td valign="top">funny! Great idea, good composition.</td>', 'funny! Great idea, good composition.', '2004-11-24 11:42:55.000000', NULL, 1),
