(1031376, 123489, 27845, '<td valign="top">This one made me laugh. I like the paradoxon in the image, and the sarcasm of the title. I''d have preferre a tighter crop on the sign though, leaving just enough of the surrounding to suggest a park. Just next to where the ribbon (hey?!) ends.</td>', 'This one made me laugh. I like the paradoxon in the image, and the sarcasm of the title. I''d have preferre a tighter crop on the sign though, leaving just enough of the surrounding to suggest a park. Just next to where the ribbon (hey?!) ends.', '2004-11-24 12:49:55.000000', NULL, 1),
(1031378, 122658, 26827, '<td valign="top">Since thelights were your subject,a  tighter crop may have worked better.  As it is, I''m forced to ignore half the shot which has very little detail.  Crop out the bottom third.</td>', 'Since thelights were your subject,a  tighter crop may have worked better.  As it is, I''m forced to ignore half the shot which has very little detail.  Crop out the bottom third.', '2004-11-24 12:50:23.000000', NULL, 1),
