(1031947, 123343, 22479, '<td valign="top">This is very cute. The look of anticipation on her face. One of the stronger entries.</td>', 'This is very cute. The look of anticipation on her face. One of the stronger entries.', '2004-11-24 19:32:40.000000', NULL, 1),
