(1031961, 123478, 21714, '<td valign="top">Beautifully done shot. It''s very powerful. Love the dramatic lighting. Well done.</td>', 'Beautifully done shot. It''s very powerful. Love the dramatic lighting. Well done.', '2004-11-24 19:51:26.000000', NULL, 1),
(1031962, 123512, 19790, '<td valign="top">hehe looks like you had some fun with that contract<br/>nicely done</td>', 'hehe looks like you had some fun with that contractnicely done', '2004-11-24 19:56:07.000000', NULL, 1),
(1031964, 123446, 21714, '<td valign="top">Clever idea that would send a lot of us back to our childhoods.  High contrast with the presence of the large shadows make it work beautifully with great impact.  It does make you feel small. Great work.</td>', 'Clever idea that would send a lot of us back to our childhoods.  High contrast with the presence of the large shadows make it work beautifully with great impact.  It does make you feel small. Great work.', '2004-11-24 19:57:05.000000', NULL, 1),
