(1031968, 122555, 2741, '<td valign="top">Excellent Color. Interesting Angle.  This is a strong entry in my opinion.</td>', 'Excellent Color. Interesting Angle.  This is a strong entry in my opinion.', '2004-11-24 20:00:07.000000', NULL, 1),
