(1034823, 122406, 22479, '<td valign="top">Clever use of props. Nice exposure, focus, and tonal range.</td>', 'Clever use of props. Nice exposure, focus, and tonal range.', '2004-11-28 05:13:58.000000', NULL, 1),
(1034825, 123290, 22479, '<td valign="top">Connection with challenge theme unclear.<br/> <br/>Sharp, well exposed.</td>', 'Connection with challenge theme unclear. Sharp, well exposed.', '2004-11-28 05:15:00.000000', NULL, 1),
(1034826, 123297, 22479, '<td valign="top">Somewhat of a small sized entry. Blue cast to the hand. Composition suffers from a lot of negative space to the left, perhaps a different crop would have improved this shot.</td>', 'Somewhat of a small sized entry. Blue cast to the hand. Composition suffers from a lot of negative space to the left, perhaps a different crop would have improved this shot.', '2004-11-28 05:16:19.000000', NULL, 1),
(1034827, 122797, 22479, '<td valign="top">Well exposed, focused well. Theme connection somewhat weak...nothing here to really indicate border patrol.</td>', 'Well exposed, focused well. Theme connection somewhat weak...nothing here to really indicate border patrol.', '2004-11-28 05:17:19.000000', NULL, 1),
(1034828, 123046, 22479, '<td valign="top">Nice entry. I would have rotated the image by a hair to level the horizon. Otherwise well exposed and focused.</td>', 'Nice entry. I would have rotated the image by a hair to level the horizon. Otherwise well exposed and focused.', '2004-11-28 05:18:05.000000', NULL, 1),
(1034829, 123412, 22479, '<td valign="top">Marvin? Ed Wood? I''m afraid I don''t quite make the connection. <br/>The saucer is a bit soft on focus due to a shallow DOF. The lighting was rather harsh. Asides from these two issues, you have an interesting entry.</td>', 'Marvin? Ed Wood? I''m afraid I don''t quite make the connection. The saucer is a bit soft on focus due to a shallow DOF. The lighting was rather harsh. Asides from these two issues, you have an interesting entry.', '2004-11-28 05:19:10.000000', NULL, 1),
(1034830, 123500, 22479, '<td valign="top">I think the white balance was a bit screwy in this shot...Perhaps a rotation to straighten out the horizon...Well exposed, and well focused overall.</td>', 'I think the white balance was a bit screwy in this shot...Perhaps a rotation to straighten out the horizon...Well exposed, and well focused overall.', '2004-11-28 05:20:30.000000', NULL, 1),
(1034831, 123495, 22479, '<td valign="top">Nice motion blur, adds interest to an otherwise mundane scene.</td>', 'Nice motion blur, adds interest to an otherwise mundane scene.', '2004-11-28 05:21:19.000000', NULL, 1),
(1034833, 122658, 22479, '<td valign="top">Well captured. Nicely saturated. Sharp and detailed.</td>', 'Well captured. Nicely saturated. Sharp and detailed.', '2004-11-28 05:21:57.000000', NULL, 1),
(1034834, 123341, 22479, '<td valign="top">Somewhat of a bluish cast. Maybe a quick levels adjustment could have fixed that. Otherwise the focus, and detail are good. Composed well, nice crop.</td>', 'Somewhat of a bluish cast. Maybe a quick levels adjustment could have fixed that. Otherwise the focus, and detail are good. Composed well, nice crop.', '2004-11-28 05:22:48.000000', NULL, 1),
(1034835, 123055, 22479, '<td valign="top">Scary guy. He looks like he''s a Type A personality.</td>', 'Scary guy. He looks like he''s a Type A personality.', '2004-11-28 05:23:17.000000', NULL, 1),
(1034836, 123305, 22479, '<td valign="top">Somewhat overexposed on the highlights and low dynamic range overall. Nice shot of the backlit flag.</td>', 'Somewhat overexposed on the highlights and low dynamic range overall. Nice shot of the backlit flag.', '2004-11-28 05:24:19.000000', NULL, 1),
(1034837, 123272, 22479, '<td valign="top">Sharp, focused, well exposed. Somewhat of an orange/warm cast to the pic overall which could have been corrected by a quick levels adjustment, unless it was an artistic gesture.</td>', 'Sharp, focused, well exposed. Somewhat of an orange/warm cast to the pic overall which could have been corrected by a quick levels adjustment, unless it was an artistic gesture.', '2004-11-28 05:25:25.000000', NULL, 1),
(1034838, 122885, 22479, '<td valign="top">Processing a bit coarse, with obvious halos around the contrasty portions.<br/>Otherwise it seems to fit well with challenge theme.</td>', 'Processing a bit coarse, with obvious halos around the contrasty portions.Otherwise it seems to fit well with challenge theme.', '2004-11-28 05:26:30.000000', NULL, 1),
(1034841, 123478, 23394, '<td valign="top">this shot is superb! if it doesn''t ribbon, it will be because not enough people tie it to the challenge.  who knows? you may get lucky...what does your reader tell you? hey, do you know what i scored this the first time through? do you know what i''m going to score it now? do you know if i changed my mind?</td>', 'this shot is superb! if it doesn''t ribbon, it will be because not enough people tie it to the challenge.  who knows? you may get lucky...what does your reader tell you? hey, do you know what i scored this the first time through? do you know what i''m going to score it now? do you know if i changed my mind?', '2004-11-28 06:50:23.000000', NULL, 1),
(1034842, 123446, 30005, '<td valign="top">Best one yet.  great light and composition.  very dramatic. A+</td>', 'Best one yet.  great light and composition.  very dramatic. A+', '2004-11-28 06:52:14.000000', NULL, 1),
(1034843, 122377, 30005, '<td valign="top">Very nice. Love the square, great light, awesome contrasts in texture and color.  A fine example of Authority in every nook and cranny</td>', 'Very nice. Love the square, great light, awesome contrasts in texture and color.  A fine example of Authority in every nook and cranny', '2004-11-28 06:57:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1034844, 123375, 23394, '<td valign="top">first impression: interesting take on the challenge.  second impression: oh boy, that sensor needs cleaning.  third impression: the image is ok, but i doubt if i would have gotten it without the title.  while i can find it visually appealling (lovely colors and rich texture, interesting angle), the dof is just too shallow.  this might have worked if the book had been pushed slightly away from the camera, so that all of the letters (top and bottom) were in focus.  as is, it leaves me feeling that this is an image in search of a subject.</td>', 'first impression: interesting take on the challenge.  second impression: oh boy, that sensor needs cleaning.  third impression: the image is ok, but i doubt if i would have gotten it without the title.  while i can find it visually appealling (lovely colors and rich texture, interesting angle), the dof is just too shallow.  this might have worked if the book had been pushed slightly away from the camera, so that all of the letters (top and bottom) were in focus.  as is, it leaves me feeling that this is an image in search of a subject.', '2004-11-28 06:59:29.000000', NULL, 1),
(1034845, 123528, 30005, '<td valign="top">this one made me look twice.  great Job. really fools the eye at first because your drawn straight to the shadow and light area in the upper left more so than the contasty figure at the bottom corner. <br/>You would think it would be the other way around since the man of steel is brighter white.<br/>Wonderful balance.</td>', 'this one made me look twice.  great Job. really fools the eye at first because your drawn straight to the shadow and light area in the upper left more so than the contasty figure at the bottom corner. You would think it would be the other way around since the man of steel is brighter white.Wonderful balance.', '2004-11-28 07:01:05.000000', NULL, 1),
(1034846, 123439, 23394, '<td valign="top">this is a tough shot to take.  you need enough light to make the boats stand out, but you don''t want to wind up with undue hotspots and flaring.  while this fits the challenge as representing symbols of authority, without a distinct subject, it comes off a bit snap-shotty.</td>', 'this is a tough shot to take.  you need enough light to make the boats stand out, but you don''t want to wind up with undue hotspots and flaring.  while this fits the challenge as representing symbols of authority, without a distinct subject, it comes off a bit snap-shotty.', '2004-11-28 07:01:48.000000', NULL, 1),
(1034847, 123455, 30005, '<td valign="top">great concept. simple and striking. Excelent thinking. A+</td>', 'great concept. simple and striking. Excelent thinking. A+', '2004-11-28 07:04:09.000000', NULL, 1),
(1034848, 122555, 30005, '<td valign="top">excelent use of primarys, interesting lines and angle. very cool</td>', 'excelent use of primarys, interesting lines and angle. very cool', '2004-11-28 07:06:14.000000', NULL, 1),
(1034849, 123515, 23394, '<td valign="top">great detail--you can even clearly see the grommets!  would prefer it rotated for the slight tilt.  might have been a bit stronger if you had backed around to the right and allowed for 10-20% more dead space in the upper right corner.</td>', 'great detail--you can even clearly see the grommets!  would prefer it rotated for the slight tilt.  might have been a bit stronger if you had backed around to the right and allowed for 10-20% more dead space in the upper right corner.', '2004-11-28 07:07:23.000000', NULL, 1),
(1034850, 122905, 30005, '<td valign="top">nice, very commercial Great effort A+</td>', 'nice, very commercial Great effort A+', '2004-11-28 07:07:41.000000', NULL, 1),
(1034852, 122425, 23394, '<td valign="top">pretty wild take on the challenge.  rather appealling, in a quirky way.</td>', 'pretty wild take on the challenge.  rather appealling, in a quirky way.', '2004-11-28 07:10:00.000000', NULL, 1),
(1034855, 122596, 23394, '<td valign="top">this is an interesting composition.  while i appreciate your humor, i think you missed a great opportunity in this challenge with your model.  her expression, shot from below, would just scream "Don''t Question Me!".  as is, i''ll give it a grin and wonder, just how does one punish a bad flamingo?</td>', 'this is an interesting composition.  while i appreciate your humor, i think you missed a great opportunity in this challenge with your model.  her expression, shot from below, would just scream "Don''t Question Me!".  as is, i''ll give it a grin and wonder, just how does one punish a bad flamingo?', '2004-11-28 07:14:11.000000', NULL, 1),
(1034856, 123412, 23394, '<td valign="top">it is hard to critique something that defies criticism...</td>', 'it is hard to critique something that defies criticism...', '2004-11-28 07:15:33.000000', NULL, 1),
(1034857, 122379, 23394, '<td valign="top">sorry, but without a title, there is no tie to the challenge.  as for the image, it has potential.  the flares are taking away from capturing the detail that would make it more interesting to really absorb, rather than one to quickly pass over.  the angle and the colors are what keep my interest.</td>', 'sorry, but without a title, there is no tie to the challenge.  as for the image, it has potential.  the flares are taking away from capturing the detail that would make it more interesting to really absorb, rather than one to quickly pass over.  the angle and the colors are what keep my interest.', '2004-11-28 07:18:39.000000', NULL, 1),
(1034860, 123435, 23394, '<td valign="top">sorry, but i don''t get this as an authority shot.  as it is arranged, there is no single subject that commands my attention.  the focus is more on the towel than the books.  do not understand how the statuette ties in with "the press".  the lighting is uneven, and the towel is uneven.  i''m sorry if you feel i am hammering this, but it looks like you want to do better (i mean, you did go to a lot more trouble than it took to submit a snapshot of a sign).  that being said, scoring points here is a matter of paying attention to details and giving the viewers/voters as few distractions as possible.  sometimes, you might have a lot of things in an image, but, if you don''t have one single thing to grab their focus, you''ll lose them immediately.  as for this image, i don''t think it is the best for the challenge.  however, as an image, i''d encourage you to revisit it and reshoot it.  smooth out the towel and work on the lighting (you might need a second light source to combat the shadows).  lower your perspective so that you are almost shooting up into the image.  make the statuette your subject, and try different dofs, until you have something that really pops.  while i also own a copy of son of mad, i think you might find something else to put in that stack that could represent controversial thought without trivializing the overall imagery.</td>', 'sorry, but i don''t get this as an authority shot.  as it is arranged, there is no single subject that commands my attention.  the focus is more on the towel than the books.  do not understand how the statuette ties in with "the press".  the lighting is uneven, and the towel is uneven.  i''m sorry if you feel i am hammering this, but it looks like you want to do better (i mean, you did go to a lot more trouble than it took to submit a snapshot of a sign).  that being said, scoring points here is a matter of paying attention to details and giving the viewers/voters as few distractions as possible.  sometimes, you might have a lot of things in an image, but, if you don''t have one single thing to grab their focus, you''ll lose them immediately.  as for this image, i don''t think it is the best for the challenge.  however, as an image, i''d encourage you to revisit it and reshoot it.  smooth out the towel and work on the lighting (you might need a second light source to combat the shadows).  lower your perspective so that you are almost shooting up into the image.  make the statuette your subject, and try different dofs, until you have something that really pops.  while i also own a copy of son of mad, i think you might find something else to put in that stack that could represent controversial thought without trivializing the overall imagery.', '2004-11-28 07:28:15.000000', NULL, 1),
(1034862, 123532, 23394, '<td valign="top">interesting image, quite sure it was not too easy to set up.  unfortunately, without the title, i''d see no tie to the challenge.  also, the hotspot on the lens is somewhat distracting.</td>', 'interesting image, quite sure it was not too easy to set up.  unfortunately, without the title, i''d see no tie to the challenge.  also, the hotspot on the lens is somewhat distracting.', '2004-11-28 07:29:52.000000', NULL, 1),
(1034863, 122491, 23394, '<td valign="top">interesting image.  the perspective also gives air to the premise that those with the money are over you.  lovely colors and textures.  good luck.</td>', 'interesting image.  the perspective also gives air to the premise that those with the money are over you.  lovely colors and textures.  good luck.', '2004-11-28 07:31:16.000000', NULL, 1),
(1034864, 122902, 23394, '<td valign="top">as many times as i have viewed this, and as long as i have viewed it, i haven''t a clue as to what it is.  yes, it has some kind of power over me, but no, i''m not feeling authority.</td>', 'as many times as i have viewed this, and as long as i have viewed it, i haven''t a clue as to what it is.  yes, it has some kind of power over me, but no, i''m not feeling authority.', '2004-11-28 07:32:56.000000', NULL, 1),
(1034865, 123501, 23394, '<td valign="top">who here has the authority...the clock, or the clock winder?  yep, you always have to wonder, who is behind the curtain.  little too much light on the hand.  nice angle.  cool clock.</td>', 'who here has the authority...the clock, or the clock winder?  yep, you always have to wonder, who is behind the curtain.  little too much light on the hand.  nice angle.  cool clock.', '2004-11-28 07:34:43.000000', NULL, 1),
(1034868, 123338, 23394, '<td valign="top">pretty wild colors in the image.  sorry to be anal here, but this comes nowhere near authority.  this is a cool shot of a beautiful spider, and it is a decidedly different twist on the challenge, but i''m not seeing authority in any sense of the word.</td>', 'pretty wild colors in the image.  sorry to be anal here, but this comes nowhere near authority.  this is a cool shot of a beautiful spider, and it is a decidedly different twist on the challenge, but i''m not seeing authority in any sense of the word.', '2004-11-28 07:39:42.000000', NULL, 1),
(1034869, 122241, 23394, '<td valign="top">it really takes more than a passing glance to catch the line of helmuts.  maybe if you had a slightly higher perspective.  looks like an interesting place to being taking photographs.  glad you didn''t make the news.</td>', 'it really takes more than a passing glance to catch the line of helmuts.  maybe if you had a slightly higher perspective.  looks like an interesting place to being taking photographs.  glad you didn''t make the news.', '2004-11-28 07:41:54.000000', NULL, 1),
(1034870, 123055, 23394, '<td valign="top">wild image, incredible expression.  probably would even be more powerful if cropped to a head shot. a bit of a stretch for the challenge, though.</td>', 'wild image, incredible expression.  probably would even be more powerful if cropped to a head shot. a bit of a stretch for the challenge, though.', '2004-11-28 07:43:50.000000', NULL, 1),
(1034871, 123024, 23394, '<td valign="top">while i appreciate your humor, the blown highlights in the trees really did this one in for me.  i would have preferred a bit more detail on the foreground cacti as well.  maybe a closer crop would have done more to convey authority.</td>', 'while i appreciate your humor, the blown highlights in the trees really did this one in for me.  i would have preferred a bit more detail on the foreground cacti as well.  maybe a closer crop would have done more to convey authority.', '2004-11-28 07:45:52.000000', NULL, 1),
(1034872, 123531, 23394, '<td valign="top">this is wild!  lovely lens work, great expression.  can''t say much for the backdrop, but hey, i guess all your money is in glass.</td>', 'this is wild!  lovely lens work, great expression.  can''t say much for the backdrop, but hey, i guess all your money is in glass.', '2004-11-28 07:47:30.000000', NULL, 1),
(1034873, 123445, 23394, '<td valign="top">nice time of day to get the right lighting.  wish you had either rotated to straighten up the tilt, or rotated to accentuate it.  the trees on the left are a distraction; i think if you played with the rotation and cropping, you''d have a killer image.</td>', 'nice time of day to get the right lighting.  wish you had either rotated to straighten up the tilt, or rotated to accentuate it.  the trees on the left are a distraction; i think if you played with the rotation and cropping, you''d have a killer image.', '2004-11-28 07:49:35.000000', NULL, 1),
(1034874, 123017, 23394, '<td valign="top">nice capture.  good colors, good perspective.</td>', 'nice capture.  good colors, good perspective.', '2004-11-28 07:50:37.000000', NULL, 1),
(1034875, 123147, 23394, '<td valign="top">this is fine for the challenge, and i''m betting your scoring will break down like this: a 5 avg (mainly 5s, mixed with some 4s, but more 6s) from those who bothered to really look at it, then a lot of 3s and 4s from those who don''t.  the trick to scoring higher is to grab the voters attention, then keep it.  here, a higher perspective that would really focus in on the road painting would have done that.  i don''t know how safe it would be, but if you had somebody else driving, you could stop your car in the road and climb on the roof or hood to get that higher perspective.  unfortunately, here, it is laying too flat to be seen immediately, when you really need it to jump out a grab attention.</td>', 'this is fine for the challenge, and i''m betting your scoring will break down like this: a 5 avg (mainly 5s, mixed with some 4s, but more 6s) from those who bothered to really look at it, then a lot of 3s and 4s from those who don''t.  the trick to scoring higher is to grab the voters attention, then keep it.  here, a higher perspective that would really focus in on the road painting would have done that.  i don''t know how safe it would be, but if you had somebody else driving, you could stop your car in the road and climb on the roof or hood to get that higher perspective.  unfortunately, here, it is laying too flat to be seen immediately, when you really need it to jump out a grab attention.', '2004-11-28 07:59:25.000000', NULL, 1),
(1034876, 123391, 23394, '<td valign="top">nice colors.  as for the challenge, it comes across a little more snap-shotty than as a strong image of authority.</td>', 'nice colors.  as for the challenge, it comes across a little more snap-shotty than as a strong image of authority.', '2004-11-28 08:01:24.000000', NULL, 1),
(1034877, 123226, 23394, '<td valign="top">interesting take on the challenge.  must have been a challenge getting the shot off, as well.</td>', 'interesting take on the challenge.  must have been a challenge getting the shot off, as well.', '2004-11-28 08:02:45.000000', NULL, 1),
(1034879, 123333, 23394, '<td valign="top">interesting composition.  if you aren''t going to rotate for the horizon, you probably would be better served rotating to accentuate the tilt.  the trees are distraction.</td>', 'interesting composition.  if you aren''t going to rotate for the horizon, you probably would be better served rotating to accentuate the tilt.  the trees are distraction.', '2004-11-28 08:04:26.000000', NULL, 1),
(1034880, 123237, 23394, '<td valign="top">clever take on the challenge.  i''m sure you speak for both the formerly dq''d as well as hacker-wannabees.</td>', 'clever take on the challenge.  i''m sure you speak for both the formerly dq''d as well as hacker-wannabees.', '2004-11-28 08:06:33.000000', NULL, 1),
(1034881, 123447, 23394, '<td valign="top">a macro like this is begging for razor sharp focus.  the lighting is fine (maybe could be toned down just a hair), and the dof is ok.  keep in mind, viewers are more comfortable when faces (even toy faces) are in focus (unless, of course, your intent is to disturb...).</td>', 'a macro like this is begging for razor sharp focus.  the lighting is fine (maybe could be toned down just a hair), and the dof is ok.  keep in mind, viewers are more comfortable when faces (even toy faces) are in focus (unless, of course, your intent is to disturb...).', '2004-11-28 08:08:29.000000', NULL, 1),
(1034882, 123530, 23394, '<td valign="top">very interesting composition.  like the colors, lines, and angles.  as for the challenge, i don''t know if you''ll lose out of the international voters who may be unfamiliar with the mayo''s.</td>', 'very interesting composition.  like the colors, lines, and angles.  as for the challenge, i don''t know if you''ll lose out of the international voters who may be unfamiliar with the mayo''s.', '2004-11-28 08:10:35.000000', NULL, 1),
(1034883, 123524, 23394, '<td valign="top">even worse is to find your car was towed for unpaid parking tickets, and then to have to pay all the tickets and the tow charge...yep, a couple quarters can go a long way.  i think your image is ok, but could have been stronger if the ticket was pulled out to cover the hotspots on the envelope edge, and maybe shot rotated a little to the right so as to make the DO NOT SEND CASH really stand out.</td>', 'even worse is to find your car was towed for unpaid parking tickets, and then to have to pay all the tickets and the tow charge...yep, a couple quarters can go a long way.  i think your image is ok, but could have been stronger if the ticket was pulled out to cover the hotspots on the envelope edge, and maybe shot rotated a little to the right so as to make the DO NOT SEND CASH really stand out.', '2004-11-28 08:14:11.000000', NULL, 1),
(1034884, 122782, 23394, '<td valign="top">cute dog.  little out of focus, though.</td>', 'cute dog.  little out of focus, though.', '2004-11-28 08:15:00.000000', NULL, 1),
(1034886, 123374, 23394, '<td valign="top">great shot.  hits the challenge dead on.  while it runs the danger of being a snapshot, it is clear, concise, and visually appealling without having to really think about it.</td>', 'great shot.  hits the challenge dead on.  while it runs the danger of being a snapshot, it is clear, concise, and visually appealling without having to really think about it.', '2004-11-28 08:19:38.000000', NULL, 1),
(1034887, 122601, 23394, '<td valign="top">authority figure or terrorist...it all depends on whether you''ve been on the bottom rung or not.  lighting is a little strong, and there is (sorry to say this, but it''s true in my home, too) too much clutter.  i don''t know what your camera''s capabilities are, but if you really tightened down on the fstop and set the shutter fairly high, you could almost black out the background, keeping the light on the boys on the ladder.</td>', 'authority figure or terrorist...it all depends on whether you''ve been on the bottom rung or not.  lighting is a little strong, and there is (sorry to say this, but it''s true in my home, too) too much clutter.  i don''t know what your camera''s capabilities are, but if you really tightened down on the fstop and set the shutter fairly high, you could almost black out the background, keeping the light on the boys on the ladder.', '2004-11-28 08:23:56.000000', NULL, 1),
(1034888, 123533, 23394, '<td valign="top">yes, this is a symbol of authority, meeting the challenge.  as an image, though, it needs work.  the wrinkles in the background are distracting, as are the hotspots on the gavel.  if that is dust in the foreground, it shouldn''t be there, as is whatever the white spot in the middle.  it''s a little too tightly cropped, and the lighting is uneven from front to back.  if that is your intention, it probably woud have been better with a different angle (try it with the handle goes more to the upper right corner).  and, i hope this is not the case, it appears that you have a set of hot pixels on your sensor.</td>', 'yes, this is a symbol of authority, meeting the challenge.  as an image, though, it needs work.  the wrinkles in the background are distracting, as are the hotspots on the gavel.  if that is dust in the foreground, it shouldn''t be there, as is whatever the white spot in the middle.  it''s a little too tightly cropped, and the lighting is uneven from front to back.  if that is your intention, it probably woud have been better with a different angle (try it with the handle goes more to the upper right corner).  and, i hope this is not the case, it appears that you have a set of hot pixels on your sensor.', '2004-11-28 08:29:15.000000', NULL, 1),
(1034890, 123453, 23394, '<td valign="top">this image would be fine without that white dot.  it really kills the image.</td>', 'this image would be fine without that white dot.  it really kills the image.', '2004-11-28 08:30:55.000000', NULL, 1),
(1034891, 123498, 23394, '<td valign="top">cute, darling baby, Yes!  authority shot, no...</td>', 'cute, darling baby, Yes!  authority shot, no...', '2004-11-28 08:31:55.000000', NULL, 1),
(1034892, 122538, 29535, '<td valign="top">Dude...  Little OTT</td>', 'Dude...  Little OTT', '2004-11-28 08:36:39.000000', NULL, 1),
(1034908, 123445, 12311, '<td valign="top">Very good shot.  While the sun has produced some high contrast shadows, I think that actually enhances the effect.</td>', 'Very good shot.  While the sun has produced some high contrast shadows, I think that actually enhances the effect.', '2004-11-28 09:26:13.000000', NULL, 1),
(1034911, 123491, 12311, '<td valign="top">Good idea, well composed.  To improve on it, I''d suggest a larger format to make the list more readable.  Also, the white balance could be adjusted to lessen the yellow cast.</td>', 'Good idea, well composed.  To improve on it, I''d suggest a larger format to make the list more readable.  Also, the white balance could be adjusted to lessen the yellow cast.', '2004-11-28 09:28:36.000000', NULL, 1),
(1034913, 122538, 12311, '<td valign="top">A tad bizzare...  Not sure I see any "authority" here - violence and power, yes, but no authority.</td>', 'A tad bizzare...  Not sure I see any "authority" here - violence and power, yes, but no authority.', '2004-11-28 09:30:44.000000', NULL, 1),
(1034916, 122313, 12311, '<td valign="top">Nice idea.   To improve on a shot like this, I''d suggest a shorter exposure, and a lens hood to cut down on the glare.</td>', 'Nice idea.   To improve on a shot like this, I''d suggest a shorter exposure, and a lens hood to cut down on the glare.', '2004-11-28 09:36:38.000000', NULL, 1),
(1034917, 122905, 12311, '<td valign="top">Great idea!  For added effect, I would have liked to see the cigarettes lit.  Still, nice work!</td>', 'Great idea!  For added effect, I would have liked to see the cigarettes lit.  Still, nice work!', '2004-11-28 09:41:03.000000', NULL, 1),
(1034918, 122953, 12311, '<td valign="top">Excellent DOF.  I love the hills and trees in the background.</td>', 'Excellent DOF.  I love the hills and trees in the background.', '2004-11-28 09:42:51.000000', NULL, 1),
(1034920, 123299, 12311, '<td valign="top">I love where you placed the focus - on the woman cowering before the authority of her attacker.  While the subdued lighting works here, I just wish it weren''t quite so flat.  Nice job!</td>', 'I love where you placed the focus - on the woman cowering before the authority of her attacker.  While the subdued lighting works here, I just wish it weren''t quite so flat.  Nice job!', '2004-11-28 09:47:21.000000', NULL, 1),
(1034924, 123428, 12311, '<td valign="top">Nice idea.  I think it would have worked better if you had the kids crying instead of smiling.  ...Then again, that would have been cruel ;-)</td>', 'Nice idea.  I think it would have worked better if you had the kids crying instead of smiling.  ...Then again, that would have been cruel ;-)', '2004-11-28 09:51:43.000000', NULL, 1),
(1034925, 123507, 12311, '<td valign="top">I love the high key effect here, although I don''t think the majority of voters will agree with me.  ...That''s a shame.  Nice job!</td>', 'I love the high key effect here, although I don''t think the majority of voters will agree with me.  ...That''s a shame.  Nice job!', '2004-11-28 09:53:00.000000', NULL, 1),
(1034927, 123508, 12311, '<td valign="top">Or, "Get back to your music lessons, jerk!"  ;-)  Nice idea.</td>', 'Or, "Get back to your music lessons, jerk!"  ;-)  Nice idea.', '2004-11-28 09:55:48.000000', NULL, 1),
(1034949, 123384, 26151, '<td valign="top">Nice capture of the moment which definitely defines the challenge. Perhaps a tighter zoom of the players and coach. If you didn''t have better zoom capabilities (my camera wouldn''t have), then a crop would work. Maybe one just including just the coach, Loren Woods and Lamond Murray would work better. (Okay I cheated, I looked up the roster). Unless you wanted to show that the coach was exercizing his authority in front of all the fans. Then it works well.</td>', 'Nice capture of the moment which definitely defines the challenge. Perhaps a tighter zoom of the players and coach. If you didn''t have better zoom capabilities (my camera wouldn''t have), then a crop would work. Maybe one just including just the coach, Loren Woods and Lamond Murray would work better. (Okay I cheated, I looked up the roster). Unless you wanted to show that the coach was exercizing his authority in front of all the fans. Then it works well.', '2004-11-28 10:48:25.000000', NULL, 1),
(1034959, 123303, 22384, '<td valign="top">I like the way this image is framed and the crisp focus on your subject: the basketball is stunning and the flag on the sleeve is a nice touch. The posture of your subject is perfect; as the wife of a basketball coach, I can''t tell you how many times I have seen this stance. Really nice shot which fits the challenge well with a twist. Great job.</td>', 'I like the way this image is framed and the crisp focus on your subject: the basketball is stunning and the flag on the sleeve is a nice touch. The posture of your subject is perfect; as the wife of a basketball coach, I can''t tell you how many times I have seen this stance. Really nice shot which fits the challenge well with a twist. Great job.', '2004-11-28 11:08:12.000000', NULL, 1),
(1034960, 123381, 22384, '<td valign="top">Lobster gags me and as the daughter of a farmer, boy do I understand what you are saying with this image. Great political statement. I think I would have framed it a bit more creatively, but it does get my attention.</td>', 'Lobster gags me and as the daughter of a farmer, boy do I understand what you are saying with this image. Great political statement. I think I would have framed it a bit more creatively, but it does get my attention.', '2004-11-28 11:09:33.000000', NULL, 1),
(1034963, 122391, 22384, '<td valign="top">I am somewhat confused by this image, but it doesn''t completely miss the mark. The clear focus on both of the women''s faces works well. I especially like the one in back. I would have cropped to just her, great expression. It does communicate well.</td>', 'I am somewhat confused by this image, but it doesn''t completely miss the mark. The clear focus on both of the women''s faces works well. I especially like the one in back. I would have cropped to just her, great expression. It does communicate well.', '2004-11-28 11:11:39.000000', NULL, 1),
(1034965, 122551, 22384, '<td valign="top">Interesting angle. Lincoln looks so forlorn in this rendering. Beautiful value range and use of light and shadow. I think shooting this in profile was a good decision.</td>', 'Interesting angle. Lincoln looks so forlorn in this rendering. Beautiful value range and use of light and shadow. I think shooting this in profile was a good decision.', '2004-11-28 11:13:19.000000', NULL, 1),
(1034966, 123338, 22384, '<td valign="top">I think that this image is stunning. It makes me itchy. Great use of color and fascinating take on the challenge. It works for me. The lighting is very nice. Awesome image.</td>', 'I think that this image is stunning. It makes me itchy. Great use of color and fascinating take on the challenge. It works for me. The lighting is very nice. Awesome image.', '2004-11-28 11:14:55.000000', NULL, 1),
(1034967, 123452, 29310, '<td valign="top">Nice shot</td>', 'Nice shot', '2004-11-28 11:15:53.000000', NULL, 1),
(1034968, 123374, 22384, '<td valign="top">Brilliant colors and great technical focus. I wish I could get images this crisp. Funny how we as a society sometimes over do the rules. This image captures that, with a sense of humor, very nicely. It bothers me that the signs are just slightly off plumb. I would either go for more of a skew or make it square. I would have cropped in a bit closer, too. Nice image.</td>', 'Brilliant colors and great technical focus. I wish I could get images this crisp. Funny how we as a society sometimes over do the rules. This image captures that, with a sense of humor, very nicely. It bothers me that the signs are just slightly off plumb. I would either go for more of a skew or make it square. I would have cropped in a bit closer, too. Nice image.', '2004-11-28 11:18:15.000000', NULL, 1),
(1034971, 122555, 26151, '<td valign="top">Like the skewed angle, makes for a more interesting shot of a boring sign. Although, the sign is very colorful. I like the way the top of the fence cuts the corner too.</td>', 'Like the skewed angle, makes for a more interesting shot of a boring sign. Although, the sign is very colorful. I like the way the top of the fence cuts the corner too.', '2004-11-28 11:22:22.000000', NULL, 1),
(1034972, 122538, 22384, '<td valign="top">This image just plain bothers me. I am sure you have heard that a gazillion times so I am sorry if that is the case. There are so many hard working nurses, that I think this sells them out. I know, I know, it is intended as artistic expression. The angle makes her look more like the victim, but then that expression on her face blows that theory. Intense and effective use of color. Great lipstick; it certainly parallels the concept and makes it look as if maybe she has taken a bite or two of her victims. I have to say this image certainly got my attention and evoked emotion. Yikes!</td>', 'This image just plain bothers me. I am sure you have heard that a gazillion times so I am sorry if that is the case. There are so many hard working nurses, that I think this sells them out. I know, I know, it is intended as artistic expression. The angle makes her look more like the victim, but then that expression on her face blows that theory. Intense and effective use of color. Great lipstick; it certainly parallels the concept and makes it look as if maybe she has taken a bite or two of her victims. I have to say this image certainly got my attention and evoked emotion. Yikes!', '2004-11-28 11:22:53.000000', NULL, 1),
(1034973, 122315, 22384, '<td valign="top">I wish this image were bigger so I could see it more clearly. I got great advice from another person on my last challenge. Make one side at least 640 and then go down from there until you get under 150 pixels total. Great use of light and color. I wish I could make out the girl''s expression.</td>', 'I wish this image were bigger so I could see it more clearly. I got great advice from another person on my last challenge. Make one side at least 640 and then go down from there until you get under 150 pixels total. Great use of light and color. I wish I could make out the girl''s expression.', '2004-11-28 11:25:44.000000', NULL, 1),
(1034974, 122905, 29310, '<td valign="top">This is great!  This is what I think of when I think of authority - and I''m not Catholic!</td>', 'This is great!  This is what I think of when I think of authority - and I''m not Catholic!', '2004-11-28 11:28:01.000000', NULL, 1),
(1034976, 123237, 22384, '<td valign="top">I know there is a great message here, I am just a bit uncertain what it is. Are you saying you didn''t keep your original EXIF tags so you can''t submit the original image, or are you saying something more intense like the changing of the individual? Either way it is a striking image. I love the blue cast, very furturistic/sci-fi. I like that the hands are sightly blurred to indicated their movement. The point of view and angle work very well. Captivating image.</td>', 'I know there is a great message here, I am just a bit uncertain what it is. Are you saying you didn''t keep your original EXIF tags so you can''t submit the original image, or are you saying something more intense like the changing of the individual? Either way it is a striking image. I love the blue cast, very furturistic/sci-fi. I like that the hands are sightly blurred to indicated their movement. The point of view and angle work very well. Captivating image.', '2004-11-28 11:30:45.000000', NULL, 1),
(1034977, 123500, 22384, '<td valign="top">I like the concept of this image. I would like all of the red lights to be crisp and clear to make the act of defiance by running them even more complete. Did you use a tripod with this shot? Was the blur on the red lights intentional to make a statement that I am somehow missing? Great idea.</td>', 'I like the concept of this image. I would like all of the red lights to be crisp and clear to make the act of defiance by running them even more complete. Did you use a tripod with this shot? Was the blur on the red lights intentional to make a statement that I am somehow missing? Great idea.', '2004-11-28 11:33:28.000000', NULL, 1),
(1034979, 123345, 22384, '<td valign="top">Great angle and point of view. Nice clean lines. I would like to see this image in color since the car dominates it.</td>', 'Great angle and point of view. Nice clean lines. I would like to see this image in color since the car dominates it.', '2004-11-28 11:34:28.000000', NULL, 1),
(1034981, 123441, 22384, '<td valign="top">Oh, I so agree with this concept. I considered this idea, but decided on something else. I would like to see the brightness up a bit and the angle of the shot squared up since time is so linear and unforgiving. Great point of view - looking up with time looming over the viewer.</td>', 'Oh, I so agree with this concept. I considered this idea, but decided on something else. I would like to see the brightness up a bit and the angle of the shot squared up since time is so linear and unforgiving. Great point of view - looking up with time looming over the viewer.', '2004-11-28 11:36:40.000000', NULL, 1),
(1034982, 122582, 22384, '<td valign="top">This image works very well for me. The shadow of the cross falling across the book adds the final touch and allows you to place your focal point square in the center without it seeming to be. I like the angle of the light and how that also focuses the viewer on the Bible. Great shot. I wouldn''t have weakened this powerful image with the qualifier in the title (for some). Let the image stand alone because it works so well. The qualifier makes your statement seem wishy-washy, and I don'' t think that was your intention. With a religious or political statement, stand firm. Don''t worry about being politically correct.</td>', 'This image works very well for me. The shadow of the cross falling across the book adds the final touch and allows you to place your focal point square in the center without it seeming to be. I like the angle of the light and how that also focuses the viewer on the Bible. Great shot. I wouldn''t have weakened this powerful image with the qualifier in the title (for some). Let the image stand alone because it works so well. The qualifier makes your statement seem wishy-washy, and I don'' t think that was your intention. With a religious or political statement, stand firm. Don''t worry about being politically correct.', '2004-11-28 11:41:28.000000', NULL, 1),
(1034984, 123439, 22384, '<td valign="top">Nice image and use of motif. I like the lights but wish they weren''t so fuzzy.</td>', 'Nice image and use of motif. I like the lights but wish they weren''t so fuzzy.', '2004-11-28 11:42:19.000000', NULL, 1),
(1034985, 123318, 22384, '<td valign="top">I like this image. Nice use of lighting and color. I would like to have seen a more creative cropping/framing, but the angle is creative and aligns with the star in the center of the badge so it does work.</td>', 'I like this image. Nice use of lighting and color. I would like to have seen a more creative cropping/framing, but the angle is creative and aligns with the star in the center of the badge so it does work.', '2004-11-28 11:44:02.000000', NULL, 1),
(1034987, 123034, 22384, '<td valign="top">Too funny. Great eye and brillant shot. I think it is perfectly framed and fascinating.</td>', 'Too funny. Great eye and brillant shot. I think it is perfectly framed and fascinating.', '2004-11-28 11:45:15.000000', NULL, 1),
(1034988, 122902, 22384, '<td valign="top">Brilliant image. Nice job editing. I''m thinking laws of gravity/nature.</td>', 'Brilliant image. Nice job editing. I''m thinking laws of gravity/nature.', '2004-11-28 11:46:11.000000', NULL, 1),
(1034990, 122313, 22384, '<td valign="top">This image needs some work. The brilliant light could work as your message, but it is too overwhelming and messy.</td>', 'This image needs some work. The brilliant light could work as your message, but it is too overwhelming and messy.', '2004-11-28 11:47:21.000000', NULL, 1),
(1034991, 123305, 22384, '<td valign="top">This is a captivating image. I like the idea. I would have shot it from even more of an point of view from below looking up. The blown out whites distract me from the great line and power of the subject.</td>', 'This is a captivating image. I like the idea. I would have shot it from even more of an point of view from below looking up. The blown out whites distract me from the great line and power of the subject.', '2004-11-28 11:48:55.000000', NULL, 1),
(1034993, 122782, 22384, '<td valign="top">I gotta tell you, I love dogs. This is a great concept, and the badge is a brilliant touch. I would like to see this animal''s eyes open with some sort of expression. Excellent detail.</td>', 'I gotta tell you, I love dogs. This is a great concept, and the badge is a brilliant touch. I would like to see this animal''s eyes open with some sort of expression. Excellent detail.', '2004-11-28 11:50:58.000000', NULL, 1),
(1034995, 123489, 22384, '<td valign="top">Perfect! Great statement.</td>', 'Perfect! Great statement.', '2004-11-28 11:53:00.000000', NULL, 1),
(1034999, 122885, 22384, '<td valign="top">Indeed. Great statement. The angle is a bit off; iIwould like to see this squared up and rigid like the orders of the sign.</td>', 'Indeed. Great statement. The angle is a bit off; iIwould like to see this squared up and rigid like the orders of the sign.', '2004-11-28 11:54:38.000000', NULL, 1),
(1035000, 122538, 10634, '<td valign="top">Probably won''t do well here because the people here don''t tend to like gory photos, but I like it. Couple of criticisms, though. First off, it is way too small. Try to take full advantage of the maximum size. If you need pointers, PM me. Also, I would have liked to have the whole meat cleaver in the frame.</td>', 'Probably won''t do well here because the people here don''t tend to like gory photos, but I like it. Couple of criticisms, though. First off, it is way too small. Try to take full advantage of the maximum size. If you need pointers, PM me. Also, I would have liked to have the whole meat cleaver in the frame.', '2004-11-28 11:55:46.000000', NULL, 1),
(1035002, 123455, 10634, '<td valign="top">Great idea and well executed.</td>', 'Great idea and well executed.', '2004-11-28 11:56:40.000000', NULL, 1),
(1035003, 123289, 13352, '<td valign="top">Precious!</td>', 'Precious!', '2004-11-28 11:57:11.000000', NULL, 1),
(1035005, 122905, 10634, '<td valign="top">LOL  Brings back memories of my Catholic school days.</td>', 'LOL  Brings back memories of my Catholic school days.', '2004-11-28 11:57:47.000000', NULL, 1),
(1035006, 123528, 10634, '<td valign="top">LOL  Great idea. I love it.</td>', 'LOL  Great idea. I love it.', '2004-11-28 11:58:26.000000', NULL, 1),
(1035008, 122790, 10634, '<td valign="top">Not too sure how this will do just because some may not see the link between it and Authority, but I think it is great. This is a photo I would love to have hanging on my wall.</td>', 'Not too sure how this will do just because some may not see the link between it and Authority, but I think it is great. This is a photo I would love to have hanging on my wall.', '2004-11-28 12:00:32.000000', NULL, 1),
(1035010, 122313, 10634, '<td valign="top">I don''t really see the connection between your photo and Authority. It''s also not the most interesting sunrise photo. I am assuming that the flare is intentional, but it is really not enhancing this photo for me. Also, the bright spot where the sun is actually hurts my eyes. When I vote, the challenge topic is a small part of my score. I usually look at the overall compositon of the photo as well as the technical aspects and overall appeal. Based on these, I have to give you a 4.</td>', 'I don''t really see the connection between your photo and Authority. It''s also not the most interesting sunrise photo. I am assuming that the flare is intentional, but it is really not enhancing this photo for me. Also, the bright spot where the sun is actually hurts my eyes. When I vote, the challenge topic is a small part of my score. I usually look at the overall compositon of the photo as well as the technical aspects and overall appeal. Based on these, I have to give you a 4.', '2004-11-28 12:05:33.000000', NULL, 1),
(1035011, 122219, 10634, '<td valign="top">When the sun sets what? This is a very beautiful photo, but I just don''t get the connection between it and authority. otherwise, it''s technically sound, has great composition and is very appealing... 5</td>', 'When the sun sets what? This is a very beautiful photo, but I just don''t get the connection between it and authority. otherwise, it''s technically sound, has great composition and is very appealing... 5', '2004-11-28 12:07:32.000000', NULL, 1),
(1035059, 123524, 26151, '<td valign="top">Good idea for the challenge. Like the composition, and set up. A little dull as far as a general photo, but for the challenge it works. Perhaps omitting "To ''Authoroity''" in the title would have made more of an impact. I find people generally don''t like when you add the challenge name in the title. I can''t make out what country this is from, but it must not be America. In America we put the "cents" symbol after the number. But I found out after a recent trip to another country that we do everything backwards.</td>', 'Good idea for the challenge. Like the composition, and set up. A little dull as far as a general photo, but for the challenge it works. Perhaps omitting "To ''Authoroity''" in the title would have made more of an impact. I find people generally don''t like when you add the challenge name in the title. I can''t make out what country this is from, but it must not be America. In America we put the "cents" symbol after the number. But I found out after a recent trip to another country that we do everything backwards.', '2004-11-28 13:48:01.000000', NULL, 1),
(1035062, 123055, 3765, '<td valign="top">Wonderful capture 10</td>', 'Wonderful capture 10', '2004-11-28 14:06:37.000000', NULL, 1),
(1035063, 123512, 3765, '<td valign="top">Good use of b&amp;w. Nice depth of field. 8</td>', 'Good use of b&w. Nice depth of field. 8', '2004-11-28 14:07:23.000000', NULL, 1),
(1035090, 123507, 255, '<td valign="top">very cool. you can almost imagine him sitting on his porch, waiting on the cattle rustlers. and although, to me, his hat looks a little more burberry than cowboy, so far this is my favorite shot in the challenge. :) 10</td>', 'very cool. you can almost imagine him sitting on his porch, waiting on the cattle rustlers. and although, to me, his hat looks a little more burberry than cowboy, so far this is my favorite shot in the challenge. :) 10', '2004-11-28 15:16:55.000000', NULL, 1),
(1035097, 123446, 255, '<td valign="top">you did well capturing the emotion with the shadows.  great authority concept.</td>', 'you did well capturing the emotion with the shadows.  great authority concept.', '2004-11-28 15:28:49.000000', NULL, 1),
(1035099, 123528, 255, '<td valign="top">hehe, something about this i really like.  i normally dont care for figurines in photos, but the placement of superman is great--and the shadow is awesome.  great concept. :)</td>', 'hehe, something about this i really like.  i normally dont care for figurines in photos, but the placement of superman is great--and the shadow is awesome.  great concept. :)', '2004-11-28 15:33:16.000000', NULL, 1),
(1035103, 122425, 255, '<td valign="top">ah, the dreaded metronome, the bane of my existence as a child growing up in a musical household. great idea for the challenge.  :)</td>', 'ah, the dreaded metronome, the bane of my existence as a child growing up in a musical household. great idea for the challenge.  :)', '2004-11-28 15:36:59.000000', NULL, 1),
(1035129, 123517, 22843, '<td valign="top">Nice Picture</td>', 'Nice Picture', '2004-11-28 16:13:30.000000', NULL, 1),
(1035146, 122241, 30021, '<td valign="top">i think this photo would have had a greater impact if the man raising his arm was slightly more in focus.  How ever i belive it is still a strong image</td>', 'i think this photo would have had a greater impact if the man raising his arm was slightly more in focus.  How ever i belive it is still a strong image', '2004-11-28 16:58:26.000000', NULL, 1),
