(1035280, 123439, 14211, '<td valign="top">I like it</td>', 'I like it', '2004-11-28 19:10:09.000000', NULL, 1),
(1035283, 123449, 14211, '<td valign="top">OH    TEAH!</td>', 'OH    TEAH!', '2004-11-28 19:13:30.000000', NULL, 1),
(1035294, 123341, 14211, '<td valign="top">nice nails</td>', 'nice nails', '2004-11-28 19:27:01.000000', NULL, 1),
(1035303, 123446, 22384, '<td valign="top">The extreme, dramatic lighting, the posture of the child and the shadow of the hand fill this image with ominous intensity. The door, the light fixture, and the boy''s pajamas appear to be from an earlier era so that the image evokes the feeling of memory from the point of view of a child. Very powerful, though distrubing, image. Masterfully crafted.</td>', 'The extreme, dramatic lighting, the posture of the child and the shadow of the hand fill this image with ominous intensity. The door, the light fixture, and the boy''s pajamas appear to be from an earlier era so that the image evokes the feeling of memory from the point of view of a child. Very powerful, though distrubing, image. Masterfully crafted.', '2004-11-28 19:42:27.000000', NULL, 1),
(1035306, 123507, 19066, '<td valign="top">great effect!</td>', 'great effect!', '2004-11-28 19:45:21.000000', NULL, 1),
(1035315, 122377, 22384, '<td valign="top">Intense shot. The idea that books are pristine, sacred items not to really be touched much if one can help it evokes the idea that perhaps we care for our books better than we care for our children. This is an amazing shot, well framed and perfectly lit. The image speaks volumes (forgive the pun; I couldn''t help myself.) The photographer is a master of image as statement.</td>', 'Intense shot. The idea that books are pristine, sacred items not to really be touched much if one can help it evokes the idea that perhaps we care for our books better than we care for our children. This is an amazing shot, well framed and perfectly lit. The image speaks volumes (forgive the pun; I couldn''t help myself.) The photographer is a master of image as statement.', '2004-11-28 19:53:15.000000', NULL, 1),
(1035318, 123024, 22384, '<td valign="top">This is a fascinating shot. I am uncetain of the symbolism given the title, but it is certainly thought-provoking.</td>', 'This is a fascinating shot. I am uncetain of the symbolism given the title, but it is certainly thought-provoking.', '2004-11-28 19:54:27.000000', NULL, 1),
(1035323, 123234, 22384, '<td valign="top">I like the idea of this shot, and I like the framing. The blown out whites distract from you subject. Again, the use of space is excellent and the choice to use the rosary beads as a backdrop work very well for me.</td>', 'I like the idea of this shot, and I like the framing. The blown out whites distract from you subject. Again, the use of space is excellent and the choice to use the rosary beads as a backdrop work very well for me.', '2004-11-28 19:57:53.000000', NULL, 1),
