(1037130, 123435, 19408, '<td valign="top">the image somewhat conveys authority. A slight variation on an overused subject. I think the image can be improved if the background was made less noticeable. Put more distance between the subject and background to accomplish this.and stronger lighting will make it go whiter.</td>', 'the image somewhat conveys authority. A slight variation on an overused subject. I think the image can be improved if the background was made less noticeable. Put more distance between the subject and background to accomplish this.and stronger lighting will make it go whiter.', '2004-11-29 23:38:12.000000', NULL, 1),
(1037131, 123343, 19408, '<td valign="top">Doesn''t illustrate the challenge. Nice kitty. You managed to avoid flash in the kitty which is always good.</td>', 'Doesn''t illustrate the challenge. Nice kitty. You managed to avoid flash in the kitty which is always good.', '2004-11-29 23:39:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1037136, 122353, 19408, '<td valign="top">Strong graphics. Good simple composition though i don''t understand the significance of the reflection.</td>', 'Strong graphics. Good simple composition though i don''t understand the significance of the reflection.', '2004-11-29 23:42:12.000000', NULL, 1),
(1037142, 123016, 1031, '<td valign="top">I can read it anyway ... still remember some German from High School.</td>', 'I can read it anyway ... still remember some German from High School.', '2004-11-29 23:44:42.000000', NULL, 1),
