(1037151, 123333, 19408, '<td valign="top">Really nice subject. Perhaps an exposure nearer to sunset would give a better color background rather than near black. It also seems a litle dark could the exposure have been longer? Could the shot have been improved by minimizing the skyline and shooting from a lower angle? Great subject.</td>', 'Really nice subject. Perhaps an exposure nearer to sunset would give a better color background rather than near black. It also seems a litle dark could the exposure have been longer? Could the shot have been improved by minimizing the skyline and shooting from a lower angle? Great subject.', '2004-11-29 23:48:29.000000', NULL, 1),
(1037155, 122782, 1031, '<td valign="top">This dog really does have a lot of power ... I''m guessing a reaction is enough to hold a plane on the ground.</td>', 'This dog really does have a lot of power ... I''m guessing a reaction is enough to hold a plane on the ground.', '2004-11-29 23:52:48.000000', NULL, 1),
