(1037165, 123394, 1031, '<td valign="top">Don''t count on it -- with a feline you may be wasting your breath.</td>', 'Don''t count on it -- with a feline you may be wasting your breath.', '2004-11-29 23:56:49.000000', NULL, 1),
(1037171, 122756, 28742, '<td valign="top">and I heard on th news today that the MPAA is trying to get a law passed REQUIRING viewers to watch the commercials and previews on DVDs! Aaargh!<br/>...oh - I like the concept and the shot is well cropped and decent lighting. Good job.</td>', 'and I heard on th news today that the MPAA is trying to get a law passed REQUIRING viewers to watch the commercials and previews on DVDs! Aaargh!...oh - I like the concept and the shot is well cropped and decent lighting. Good job.', '2004-11-29 23:59:00.000000', NULL, 1),
(1037173, 123207, 28742, '<td valign="top">I''m sure I won''t be the first to say that I thought that was the boy''s hand with the pen at first. :-)  I like this one.</td>', 'I''m sure I won''t be the first to say that I thought that was the boy''s hand with the pen at first. :-)  I like this one.', '2004-11-30 00:00:05.000000', NULL, 1),
