(1038912, 123381, 29777, '<td valign="top">I like this image on many levels. So many caption possibilities. I have to reach to see the relation to the challenge. The caption helps.</td>', 'I like this image on many levels. So many caption possibilities. I have to reach to see the relation to the challenge. The caption helps.', '2004-11-30 18:51:19.000000', NULL, 1),
(1038913, 123299, 23362, '<td valign="top">Damn! This evokes an emotion...that''s for sure.  I think a tad more contrast would help. I like that it is rendered in black and white.  Powerful illustration! [I hope it''s an photographic illustration!  :::shudder::]</td>', 'Damn! This evokes an emotion...that''s for sure.  I think a tad more contrast would help. I like that it is rendered in black and white.  Powerful illustration! [I hope it''s an photographic illustration!  :::shudder::]', '2004-11-30 18:51:34.000000', NULL, 1),
(1038914, 123034, 23458, '<td valign="top">hehehe.... shame this wasn''t in the humour challenge. Like the comedic side, but the photo itself doesn''t hold much interest. 6.</td>', 'hehehe.... shame this wasn''t in the humour challenge. Like the comedic side, but the photo itself doesn''t hold much interest. 6.', '2004-11-30 18:52:13.000000', NULL, 1),
(1038919, 122797, 23362, '<td valign="top">I think this picture is too "busy" with no real message or center of interest.</td>', 'I think this picture is too "busy" with no real message or center of interest.', '2004-11-30 18:53:27.000000', NULL, 1),
(1038924, 122843, 23312, '<td valign="top">Nice - clever image of "authority" and a well done photo.  If you had a bulldozer handy I''d have got rid of those buildings on the right - or maybe a slight change of angle could have got them out of the frame and still left the sign legible?</td>', 'Nice - clever image of "authority" and a well done photo.  If you had a bulldozer handy I''d have got rid of those buildings on the right - or maybe a slight change of angle could have got them out of the frame and still left the sign legible?', '2004-11-30 18:54:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1038925, 123455, 23458, '<td valign="top">Really like the composition here... and what''s that... my god, a border that actually works - love how the lines on the board blend into the border. <br/> <br/>Great idea, your onto a winner here. 9.</td>', 'Really like the composition here... and what''s that... my god, a border that actually works - love how the lines on the board blend into the border.  Great idea, your onto a winner here. 9.', '2004-11-30 18:54:42.000000', NULL, 1),
(1038927, 123532, 29777, '<td valign="top">Very eye catching. Which way is the laser entering the lens? Cool photo. A bit of a stretch to meet the challenge to me. Is the blue tone intentional?</td>', 'Very eye catching. Which way is the laser entering the lens? Cool photo. A bit of a stretch to meet the challenge to me. Is the blue tone intentional?', '2004-11-30 18:54:53.000000', NULL, 1),
(1038929, 123460, 23458, '<td valign="top">Love the smirk on the referees face. Other than that I think you are a little too far from the action for this to be massively effective, but a good effort nonetheless.</td>', 'Love the smirk on the referees face. Other than that I think you are a little too far from the action for this to be massively effective, but a good effort nonetheless.', '2004-11-30 18:55:57.000000', NULL, 1),
(1038930, 123450, 29777, '<td valign="top">Looks like a noble woman. You can see the wisdom of age. Looks fragile but not frail. Nice.</td>', 'Looks like a noble woman. You can see the wisdom of age. Looks fragile but not frail. Nice.', '2004-11-30 18:56:50.000000', NULL, 1),
(1038932, 122885, 23362, '<td valign="top">Strong point: depth of field. Weak point: an image easy to forget.</td>', 'Strong point: depth of field. Weak point: an image easy to forget.', '2004-11-30 18:57:10.000000', NULL, 1),
(1038938, 122538, 23312, '<td valign="top">Doesn''t really say "authority" to me so much as "psycho"...</td>', 'Doesn''t really say "authority" to me so much as "psycho"...', '2004-11-30 18:58:24.000000', NULL, 1),
(1038940, 123433, 23458, '<td valign="top">The square crop here works well, good dof , other than that ... it''s yet another bible, - not anything here that really jumps out at me... but good technical work. 6.</td>', 'The square crop here works well, good dof , other than that ... it''s yet another bible, - not anything here that really jumps out at me... but good technical work. 6.', '2004-11-30 18:58:53.000000', NULL, 1),
(1038941, 123539, 29777, '<td valign="top">I didn''t get it at first. For some reason I saw the rock as a burn mark on the paper. I like the clever relationship to the challenge. I guess some shadow would help give depth to the rock and give the whole thing more impact.</td>', 'I didn''t get it at first. For some reason I saw the rock as a burn mark on the paper. I like the clever relationship to the challenge. I guess some shadow would help give depth to the rock and give the whole thing more impact.', '2004-11-30 18:59:11.000000', NULL, 1),
(1038942, 123253, 23458, '<td valign="top">NIce effect, though it appears a little dull. Could use a bit more contrast or something. <br/> <br/></td>', 'NIce effect, though it appears a little dull. Could use a bit more contrast or something.  ', '2004-11-30 18:59:40.000000', NULL, 1),
(1038944, 123024, 23458, '<td valign="top">Why is this not in the comedy challenge.... it would have got a 7 from me there.... in authority it suffers from the good old not meeting the challenge issue.<br/> <br/>sorry... 4.</td>', 'Why is this not in the comedy challenge.... it would have got a 7 from me there.... in authority it suffers from the good old not meeting the challenge issue. sorry... 4.', '2004-11-30 19:01:05.000000', NULL, 1),
(1038945, 123034, 24970, '<td valign="top">Oh wow. For a second I thought those dolphins were real. Either way, it''s a well-done picture with a great title. Nice job.</td>', 'Oh wow. For a second I thought those dolphins were real. Either way, it''s a well-done picture with a great title. Nice job.', '2004-11-30 19:01:18.000000', NULL, 1),
(1038948, 123532, 23362, '<td valign="top">Authority?  Okay, If you say so...<br/>The thing I like best about this image is that it''s a Nikkor lens.  lol</td>', 'Authority?  Okay, If you say so...The thing I like best about this image is that it''s a Nikkor lens.  lol', '2004-11-30 19:02:52.000000', NULL, 1),
(1038951, 123017, 24970, '<td valign="top">This is a very well-composed, sharp picture with emotion. Nicely done, no complaints from me.</td>', 'This is a very well-composed, sharp picture with emotion. Nicely done, no complaints from me.', '2004-11-30 19:04:10.000000', NULL, 1),
(1038954, 123453, 23362, '<td valign="top">What is that bright spot above the extended hand? A fire fly? I mean, what is it? I''m hoping this point of light isn''t some famous statue feature that I haven''t been aware of!  :::blush:::</td>', 'What is that bright spot above the extended hand? A fire fly? I mean, what is it? I''m hoping this point of light isn''t some famous statue feature that I haven''t been aware of!  :::blush:::', '2004-11-30 19:07:33.000000', NULL, 1),
(1038963, 123446, 24970, '<td valign="top">The shadow of the pointing hand is a nice detail, well thought-out. Contrast is a little much for my taste.</td>', 'The shadow of the pointing hand is a nice detail, well thought-out. Contrast is a little much for my taste.', '2004-11-30 19:13:11.000000', NULL, 1),
(1038965, 123480, 23362, '<td valign="top">Insert donut and I''d see some authority here. Does the shape of his head suggest  years of enjoying donuts? Authority = donuts?  Plump faced cops just don''t give me much citizen comfort.   I do like the inclusion of the U.S. flag, supurb depth of field. I think the lighting is rather flat for a male "authority" figure. I also like the fact the subject is looking directly into the lens.</td>', 'Insert donut and I''d see some authority here. Does the shape of his head suggest  years of enjoying donuts? Authority = donuts?  Plump faced cops just don''t give me much citizen comfort.   I do like the inclusion of the U.S. flag, supurb depth of field. I think the lighting is rather flat for a male "authority" figure. I also like the fact the subject is looking directly into the lens.', '2004-11-30 19:16:00.000000', NULL, 1),
(1038971, 123343, 24970, '<td valign="top">Nice capture. I''m not convinced the bottom third-ish of this picture is entirely necessary, though I suppose it lends a sense of height. Lighting is a bit harsh, but I appreciate the candid nature of this shot.</td>', 'Nice capture. I''m not convinced the bottom third-ish of this picture is entirely necessary, though I suppose it lends a sense of height. Lighting is a bit harsh, but I appreciate the candid nature of this shot.', '2004-11-30 19:19:43.000000', NULL, 1),
(1038977, 122241, 23362, '<td valign="top">Greatly lacking visual impact...does show a street situation that could lead to some kind of great photo...but the camera position looks way too "safe."  "Safe" meaning far away, no real expressionscaptured, no real action...just a milling crowd.</td>', 'Greatly lacking visual impact...does show a street situation that could lead to some kind of great photo...but the camera position looks way too "safe."  "Safe" meaning far away, no real expressionscaptured, no real action...just a milling crowd.', '2004-11-30 19:24:39.000000', NULL, 1),
(1038983, 122406, 24970, '<td valign="top">Haha. Nice creativity. The lighting''s a bit washed out, and the dinosaurs don''t stand out from the background quite as much as I''d like. But it''s decently composed and I appreciate the humor.</td>', 'Haha. Nice creativity. The lighting''s a bit washed out, and the dinosaurs don''t stand out from the background quite as much as I''d like. But it''s decently composed and I appreciate the humor.', '2004-11-30 19:29:04.000000', NULL, 1),
(1038991, 123460, 24970, '<td valign="top">Well composed, this really tells a story. Thanks.</td>', 'Well composed, this really tells a story. Thanks.', '2004-11-30 19:33:26.000000', NULL, 1),
(1038994, 122869, 24970, '<td valign="top">I wish this didn''t have to rely on the title quite so much to blatently fit the challenge, it''s a well-done picture otherwise. Little washed out in the bottom right, but it works.</td>', 'I wish this didn''t have to rely on the title quite so much to blatently fit the challenge, it''s a well-done picture otherwise. Little washed out in the bottom right, but it works.', '2004-11-30 19:35:32.000000', NULL, 1),
(1038995, 123033, 23362, '<td valign="top">Ha! Fine photographic illustration! Tells a story, Excllent use of perspective! It''s a "Bell-Ringer!"</td>', 'Ha! Fine photographic illustration! Tells a story, Excllent use of perspective! It''s a "Bell-Ringer!"', '2004-11-30 19:38:00.000000', NULL, 1),
(1038996, 123046, 2596, '<td valign="top">I guess Iceland</td>', 'I guess Iceland', '2004-11-30 19:38:27.000000', NULL, 1),
(1038998, 123507, 24970, '<td valign="top">The high-contrast doesn''t really work to carry the mood of this picture for me. Barring that, I really like how well laid-out this is, it''s overall a fine piece of work.</td>', 'The high-contrast doesn''t really work to carry the mood of this picture for me. Barring that, I really like how well laid-out this is, it''s overall a fine piece of work.', '2004-11-30 19:39:17.000000', NULL, 1),
(1039002, 123539, 2596, '<td valign="top">I can´t see it, but have the feeling that i´m missing it big time</td>', 'I can´t see it, but have the feeling that i´m missing it big time', '2004-11-30 19:41:06.000000', NULL, 1),
(1039003, 123363, 23362, '<td valign="top">To me this is just funny portrait, an overexposed one at that. I really don''t feel the authority emotion...but I think it is fun to look at.</td>', 'To me this is just funny portrait, an overexposed one at that. I really don''t feel the authority emotion...but I think it is fun to look at.', '2004-11-30 19:41:44.000000', NULL, 1),
(1039010, 122406, 29777, '<td valign="top">Cute. I like this. The right side looks too dark to me.</td>', 'Cute. I like this. The right side looks too dark to me.', '2004-11-30 19:44:46.000000', NULL, 1),
(1039014, 122953, 23362, '<td valign="top">Don''t ask..Don''t Tell..Don''t get it?  Is there some fine print in the sign I can''t read, that make the title more clear to the viewer?  DOn''t know...</td>', 'Don''t ask..Don''t Tell..Don''t get it?  Is there some fine print in the sign I can''t read, that make the title more clear to the viewer?  DOn''t know...', '2004-11-30 19:45:46.000000', NULL, 1),
