(1039021, 122797, 24970, '<td valign="top">Nice concept, it''s a little too busy to know what to focus on. It would help to have the car &amp; checker physically more in focus than the fence.</td>', 'Nice concept, it''s a little too busy to know what to focus on. It would help to have the car & checker physically more in focus than the fence.', '2004-11-30 19:47:18.000000', NULL, 1),
(1039022, 123508, 29777, '<td valign="top">Distrubing in its reality. Funny. I think this would have more impact looking up at him from the point of view of her right foot.</td>', 'Distrubing in its reality. Funny. I think this would have more impact looking up at him from the point of view of her right foot.', '2004-11-30 19:47:40.000000', NULL, 1),
(1039025, 123483, 29777, '<td valign="top">Interesting use of depth. Nice.</td>', 'Interesting use of depth. Nice.', '2004-11-30 19:48:22.000000', NULL, 1),
(1039026, 122681, 24970, '<td valign="top">This picture would work even better without the legs behind the ref, they don''t really add anything.</td>', 'This picture would work even better without the legs behind the ref, they don''t really add anything.', '2004-11-30 19:48:42.000000', NULL, 1),
(1039027, 123428, 29777, '<td valign="top">love the expressions, the colors, the patterns. Too bad the little one is a bit out of focus. Best one I''ve seen.</td>', 'love the expressions, the colors, the patterns. Too bad the little one is a bit out of focus. Best one I''ve seen.', '2004-11-30 19:49:30.000000', NULL, 1),
(1039030, 122582, 29777, '<td valign="top">...for some. A means of control for others. Powerful. Well done. Matches the challenge.</td>', '...for some. A means of control for others. Powerful. Well done. Matches the challenge.', '2004-11-30 19:50:59.000000', NULL, 1),
(1039031, 123445, 23362, '<td valign="top">Wish there was a sad face in that top window...needs something...even a colored ribbon hanging from one of the bars...not much for the human brain to digest here.</td>', 'Wish there was a sad face in that top window...needs something...even a colored ribbon hanging from one of the bars...not much for the human brain to digest here.', '2004-11-30 19:51:30.000000', NULL, 1),
(1039032, 123286, 29777, '<td valign="top">I think I might like this better in B&amp;W.</td>', 'I think I might like this better in B&W.', '2004-11-30 19:51:43.000000', NULL, 1),
(1039036, 123363, 29777, '<td valign="top">Who is this person. She just looks like she has a sinus condition. No sign of authority here. Good focus and detail though.</td>', 'Who is this person. She just looks like she has a sinus condition. No sign of authority here. Good focus and detail though.', '2004-11-30 19:53:05.000000', NULL, 1),
