(1039048, 123513, 29777, '<td valign="top">I don''t see the tie to the challenge. Great capture of school life. I like the image I just don''t see the tie in. Sorry.</td>', 'I don''t see the tie to the challenge. Great capture of school life. I like the image I just don''t see the tie in. Sorry.', '2004-11-30 19:58:16.000000', NULL, 1),
(1039051, 123532, 7543, '<td valign="top">Great idea!</td>', 'Great idea!', '2004-11-30 19:59:02.000000', NULL, 1),
